insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "907278e1-ceac-4f41-a9be-afba2410d7cc", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 14, "content": "Emily Holland (26:19): Yeah, I like that. And I also think we were talking about essentially firing clients or weeding out clients. And I think a great way to avoid that depending on your type of work, unless you're just continuously on retainer with someone or something like that, is to have really what may feel like very direct and powerful conversations upfront about clear expectations and success metrics so that you have a clear alignment with them on the direction that you're going to go. And obviously delivering the work as part of that. But then it's also thinking about, well, how are they going to look at this relationship and think that it's successful? There may be something that is not as obvious to you. For example, if we do a podcast project with someone and we think, well, if they get lots of listens, then they'll feel like this is success. And maybe the actual goal is just brand awareness and they don't give a shit about listens. So I think asking those kind of awkward but really important questions upfront is really helpful. And I think it shows the person that you're working with or the team that you're working with that you care about the success of your relationship, and that's what those questions sort of indicate to them.\n\nCole Heilborn (27:41): Yeah. Is that something you do for your clients?", "token_estimate": 334, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "26:19", "end_timestamp": "27:41", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "3d23ccb1-68e5-4288-aa29-f9ebbe2b70f4", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 15, "content": "Emily Holland (27:44): Yeah, I mean, I did it with you, Cole, but yeah, I try to. And then the other thing, I mean, I came from a corporate environment in which I was in account management. So this stuff is really fun for me to implement because it's not the same exact relationships I was working with Fortune 500 VPs of marketing and things like that. But it's the same principles. It's like people want to know that you care about the success of your relationship and you do, I mean, you care because you care about the person, but you also care because of the longevity of the financial reward as well. So there's sort of like you be a good person, you care about the success, and then you'll be rewarded hopefully for the success of that relationship. And then the other thing that I think is really important is intermittent touch bases. So throughout the project or the contract or whatever you're delivering, asking for feedback and making sure that if it's stuff that maybe is surprising to you or is not something you necessarily expected or want to hear, that you use it as an opportunity to improve and course correct and not as an opportunity to get offended or upset. It's not really about you per se, it's just about tweaking probably some of your processes or communication tactics and so that the rest of whatever you're working on with that person goes well.\n\nCole Heilborn (29:09): Yeah, I mean, the person you're working with is just another person. So I think it's like what would you do to maintain a good friendship or a good romantic relationship? I think it's a very similar approach, and it just generally boils down to communication and making sure that we're communicating with people", "token_estimate": 428, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "27:44", "end_timestamp": "29:09", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "979be677-fb71-4deb-8fd6-4a0a87d8d36e", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 16, "content": "Emily Holland (29:31): And being human. I mean, I think we get into these maybe not as much as in freelance, but I remember in corporate America, I mean people are so stiff and you show them a little bit of humanity, and they're so thankful for it because they really want to express themselves and be their authentic selves, but they're not feeling like they're able to in whatever environment they're in for their work. So just being human I think goes a long way with creating good client relationships.\n\nCole Heilborn (29:59): Yeah, well said.\n\nEmily Holland (30:02): Yeah. And then the other thing I wanted to bring up with that is once a project is completed or a contract is completed or whatever, how do you go about keeping in touch with that person if you're not going to immediately do new work together in a way that's not consistent selling all the time? How do you usually go about keeping in contact with past clients?", "token_estimate": 234, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "29:31", "end_timestamp": "30:02", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "e0b3a126-36df-466f-889f-b43ab158e58b", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 17, "content": "Cole Heilborn (30:26): I usually just ask 'em. So I'll do a wrap up call after every project with a client and we go over the whole thing. Usually there's some funny moments or just wild things that happened and you're like, oh, I remember that one time when I don't know whatever happened. So it's usually a good time to wrap things up and reconnect on that personal level. In that call, I will ask for feedback. We're always looking for ways to improve and trying to understand from our clients how we can do that. And I would usually ask them, Hey, one, we'd love to continue working together. Do you have any work that we could continue to chat about? Or if not, that's cool, but I'd love to stay in touch. Do you have a preference on how I do that? And that probably depends on your relationship. Maybe you see 'em up at the local ski hill every Saturday because you guys live in the same town, so you say hi every Saturday. (31:27): Or oftentimes I'll just for the clients that don't live in town, but I don't see on a regular basis, I just try to make it a point to stay in touch every quarter. If I think of them while I'm seeing something or if I am out through my daily life, if I see something that's like, oh, I think Joe over at X company would appreciate this, I might send it to 'em. Or if we finish any work that they might enjoy, I'll send it their way and just try to maintain that presence, but without being very overbearing or ready for the next project.\n\nEmily Holland (32:05): Nice. Awesome. So it's just again, human touch points, just being a good human.\n\nCole Heilborn (32:11): Yeah, I think so.", "token_estimate": 406, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "30:26", "end_timestamp": "32:11", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "5827ef30-d82d-493b-99e9-4f700f78dccf", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 18, "content": "Emily Holland (32:12): Yeah. One of the things I learned from Justine actually was to also reach out to past clients who you have good relationship with, and not only just like, Hey, I thought of you for this, but also, hey, I'm looking, I have availability for the next three months and I'm looking for more projects to take on. Do you know of anyone that could be a good fit for the type of work that we had done together or whatever? And that's gotten actually a lot of referrals from that, and whether they've turned into clients or not, that's hit or miss, but they're always good connections that eventually lead to even better connections and et cetera, et cetera. So I think that idea of asking for referrals feels like a little funny upfront, I think. But once you get used to it, it's a great way to just keep your network expanding.\n\nCole Heilborn (33:04): Yeah. I mean, if you do a good job for a client, chances are they want you to succeed. And so if you ask them for help, they're probably going to provide help however they can. So if that means a referral or whatever, I think most people are generally open to that.\n\nEmily Holland (33:19): Yeah, yeah, for sure. And how do you normally set boundaries with work? You are a business owner as a freelancer, essentially. Any freelancer is running a tiny little business of their own. How do you shut your phone off at the end of the day? How do you create boundaries so that you have a sort of clear distinction between your business and your life?\n\nCole Heilborn (33:51): Yeah, I don't know. I'm not great at that. Yeah, I'm not super good at that. I think there's\n\nEmily Holland (34:02): Something to keep working on, I guess.\n\nCole Heilborn (34:04): Yeah, I mean, I think one is trying to detach your workspace from your living space. I think that's a very common thing that we hear a lot. That doesn't always work though, because a lot of us work from home, especially Now,\n\nEmily Holland (34:20): Do you do that though? You have a separate workspace from your main living space, right?", "token_estimate": 514, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "32:12", "end_timestamp": "34:20", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "f68081e9-a349-4ec1-9682-59bf54cf0e40", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 19, "content": "Cole Heilborn (34:24): Yeah, we do. So that's been nice. But for a while I worked inside, actually, I was inside my closet in my bedroom for the first couple of years,\n\nEmily Holland (34:37): Just in the dark typing away in there\n\nCole Heilborn (34:39): Pretty much. Yeah, that's exactly what you're imagining is exactly right. So I guess I don't have the best ideas of how to create that balance. I think that balance is also, that's up for everyone to decide what that balance looks like. I think it was Chris Picard who talked about this subject. I think it was one of those clickbait YouTube videos that I clicked on like, oh, Chris Picard talking about work-life balance. This seems interesting. And what he talked about is kind of an idea or a mindset that I've tried to adopt or tried to consider with how it fits with my own situation. And his idea was that balance doesn't always mean, okay, for this week I'm going to work 40 hours and then I'm going to take the standard weekend and then be done at five o'clock and clock in at nine.\n\nEmily Holland (35:27): Sometimes", "token_estimate": 270, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "34:24", "end_timestamp": "35:27", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "6e81f772-3fb7-4ab4-a9d4-62f6428d7182", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 20, "content": "Cole Heilborn (35:27): Balance is for this quarter I'm working 50, 60, 70 hours a week, but then for the next quarter, maybe I work 20 hours a week for that entire quarter. And so I think especially in Project World where you don't always have consistent work, you're either seems to be all out or things are a little slower. And so I've tried to find that idea as finding balance. And so when I'm at work, I try to be as focused as I can. I try to be as productive with the time that I have set aside for work. But also when I go home, I'm really excited generally to keep working. I enjoy what I do, and so I'll have ideas or I'll go on a bike ride and I come back from it. I'm like, oh, shoot, here's an idea. Let me try to implement this, or lemme write this down before I forget it. But when I go on vacation or I take time off, I just try to completely shut everything off and just vacation really hard and not worry about work. And so I have found that I enjoy that. I really enjoy either being a hundred percent at work or a hundred percent away from work. And there's obviously a little bleed over there, but I found that that's currently working for me. That might change though. It probably will. But currently that's kind of where I'm at.\n\nEmily Holland (36:48): And I think that kind of goes back to those different pay structures too. It's like if you're being paid on the hourly or the day rate, it's really hard to envision a world in which you feel comfortable taking off time because you're just kind of beholden to this money coming in and your time is super valuable for your living, which is very different obviously from having a job in which you can take paid time off and you still get paid and you don't have to check in for the most part, for most good companies. So very, very different perspective. So I think that kind of goes back to figuring out the right pay structure or charging structure for clients that will eventually enable you to feel like you can vacation hard and be totally present with the people you're with or in the experience that you're trying to have.", "token_estimate": 526, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "35:27", "end_timestamp": "36:48", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "464e90c1-d1f0-4112-bc68-8c3010fd4cdd", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 21, "content": "Cole Heilborn (37:39): Totally. Yeah, I think that's a great point. Yeah, those decisions you make about how you get paid influence, I mean, they're kind of the building blocks for how you build the rest of your business. And I guess, yeah, vacation and work-life balance is kind of one of those areas as well.\n\nEmily Holland (37:55): Yeah. One thing that wasn't obvious to me, but I feel like kind of goes along the lines with boundaries and with the paying structure or the charging structure is you can decide per client how you want to be billed or how you want to bill them so that you have different income streams coming in at different times. For example, most of my clients pay once a month and that's it, but then I have a couple clients that are on a biweekly structure because I missed having a salary coming in every two weeks or whatever. That's consistent, and I know that I have to wait to purchase certain things for this time period or whatever. So how do you go about managing the highs and lows that you were just talking about when you're thinking of like, oh, I have three months on and I have a lot of projects going on, and then there's a lull and I might not have as many projects, but I still have the same amount of expenses, so how do I manage all of that? Yeah. How do you go with that high and low without it making you lose your mind?", "token_estimate": 342, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "37:39", "end_timestamp": "37:55", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "d7fc7ee8-4f24-4feb-b9d5-a8e3c2f5b133", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 22, "content": "Cole Heilborn (38:59): Yeah. Managing cashflow is a real pain if you're not super financially excited to deal with finances. I think to back up though quickly, you made a really good point. With every client, you can treat them entirely different. Just because you've done one thing with a past client doesn't mean you have to do the same thing for the next. I think I've kind of viewed each client, and I've heard this before, I think from Chase Jarvis who's a photographer, he said, treat every project. Treat every client like a brand new client and just experiment with it. See what works, see what doesn't, and don't feel like you have to do the same thing over and over with each one, figure out how to improve upon it. So thanks for bringing that up because I think that's a really good point as far as kind of managing the ebb and flow. Yeah, that is tough. It is a reality, and it's just part of being in business by yourself. Some months you make tons of money and other months you make zero money or you lose money. And figuring out how do I manage this over a quarter or a year can be very, very difficult. And if you're not careful or if you just have bad luck or you have clients who are late paying you, you're kind of at the mercy of the whim or mercy of the wind. (40:23): I, we'll go with that. I don't know what I'm trying to say, but there's only some things you can control. And I've been in situations many times where a client just hasn't paid me and they never paid me. And unfortunately for that month or two month period, it was like, oh, shoot, I have $0 and I have all these things. Spend are expenses. And that's a really sucky place to be, and I think it's kind of inevitable that you end up there at least once. And yeah, it's just the reality of doing business. And I think getting comfortable with that I think is probably the first thing that I would recommend is you can do everything in your power to avoid that, but it will happen and you kind of have to figure out how to deal with it. I think there are very practical steps you can take to try to avoid that. (41:14): Obviously, saving is a big one. Putting money away for those periods of time where you won't have work. If you're having a great month, put some of that away, save it. You never know. Next month might not be the same. I think obviously just being very aware of your living standards and what you're spending money on, and I think everything you spend money on ultimately shows you what your priorities are. And so if being in business and being self-employed is a priority, then hopefully you're making financial decisions that are supporting that and setting you up for success. I'm not saying don't spend money on fun things, but I do think you need to be realistic about how much you're making and how much you're spending. I think it comes down to even things like you might have a great year, but if you're not keeping track of your taxes and what you'll owe at the end of the year, that can come as a big surprise. (42:08): And so being aware of based on your state and what type of business you are and your tax filing, you need to be on that type of stuff and understand what do you owe and when is it due? And you should also familiarize yourself with the penalties because they are expensive and 9% every month really racks up in terms of overage charges. So I think those are some really just basic steps you can take, but it's going to happen. I think one thing to consider also is know how long it takes for you to land a new client. And so let's say you're having a great quarter, but you're not really sure what next quarter looks like. I mean, I've been in this spot many times where I'm not thinking about the future. I'm not thinking about the last half of the year because I'm just riding the wave the first six months. (43:00): And then you get to the last half and you're like, I've done no marketing, I've done no sales, and now I'm just living off of the pennies that I tucked away from that great period. And so knowing how long it takes to convert a lead and actually secure them as a client, I think is really good. And then just always be marketing. I think it's more of, I think you're good marketing is you're always doing it. You're always plugging away at it because you know that in six months from now, you might need the work even if you don't need it now.", "token_estimate": 1100, "speakers": ["Cole Heilborn"], "start_timestamp": "38:59", "end_timestamp": "38:59", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "2846e570-acb6-475b-8a23-d8bc28cc0833", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 23, "content": "Emily Holland (43:31): Yeah. Yeah. There's so much in that. I just wanted to mention a couple other things that I've been using to help me sort of figure out the cashflow thing, because it was a big shock. Obviously, I knew rationally that I would be losing every two weeks, a steady paycheck and benefits and retirement. It was still very, I knew it was going to be hard, and then it was really hard to transition into that even if you've had any type of job that gives you every two weeks or every week pay and you're moved from that to contracted work. It's a really big shift. So one of the things that I did in the first couple months is I had a general idea of my expenses, like rent, food, everything that I actually needed to live. And then I've used Mint, which is just a platform you can put all of your finances into, literally go in and note and tag every single transaction that I have on all of my cards and everything and just see what my spending actually was. (44:39): And I had to sort of come off of that salaried spending to sort of figure out what the level point was of this new life that I was in. So I did that, and I think that's really helpful, and this has been something that other people have said is helpful for them. So I started doing a money date with myself every week and having a set amount of time on Monday to look at all of my money. And I do that obviously, to stay on track with everything that I need to pay for and that I should be reminding people for invoices and stuff like that. But then I also use that as motivation to at least set out one hour that I am using to pitch or to market or something so that I have a chunk of time that, okay, this is my money situation right now. It's probably not where I want it to exactly be. So how am I going to use that to be motivated and what do I need to find as far as revenue coming in this month? Cool. I'm going to use this hour on Tuesday to pitch or market or whatever brings in business for you. So I just wanted to mention that as something that was helpful for me in the highs and lows, timeframes.", "token_estimate": 524, "speakers": ["Emily Holland"], "start_timestamp": "43:31", "end_timestamp": "43:31", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "db27b6ba-c217-44d3-b4a6-fb2e5679d70e", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 24, "content": "Cole Heilborn (45:51): Yeah, that's great. I think even if it's just blocking off, putting an hour of your time on Google Calendar every week to say, okay, I'm going to spend this time to market even if I don't really know what I'm going to be doing. I think you got to always be thinking about that stuff. I will say another tool that I have found, if folks use QuickBooks as their invoicing or accounting platform, there is a cashflow projection tool in QuickBooks, which is, you could do it in a Google sheet or a spreadsheet. It's not difficult, but it forces you or it asks you to project your income and your expenses over any given timeframe. And so you could say, okay, if I'm going to look at this year, when am I receiving money? When am my bills due? And then it gives you a way to kind of analyze that because you might, at the end of the year, you might have a profitable year, but at any particular month you might be cash negative because of the way that your payments or accounts receivable and payable have worked. And that can put you in a really hard spot too, even if you are profitable and you're doing well, there are times when you just don't have cash. And planning for that or at least being aware of that is good.", "token_estimate": 310, "speakers": ["Cole Heilborn"], "start_timestamp": "45:51", "end_timestamp": "45:51", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "8af18162-bd5d-416e-ad0e-f426eac47da4", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 25, "content": "Emily Holland (47:07): Yeah, I think that's really helpful. I use Wave. It's similar to QuickBooks, so any of those, I think that has that as on there as well. The other thing you can do with taxes that people probably know about if they're in the freelancing space, but if you're new to freelancing, you can do sort of estimated quarterly taxes. So you're paying as you go instead of getting to the April of next year and having a huge lump sum that you might have to pay. So you're less surprised at that time, and you kind of already have paid essentially what you think you'll owe, but there'll be some right sizing to that. But my accountant recommended that I do that, and it's been really helpful for my sanity to be honest. I'm just like, cool, I already paid a good chunk of that, so hopefully that's good enough for that. But then of course you still have to do your taxes. (48:01): You mentioned something that is interesting, which is putting money back into the business. I mean, for your type of work, there's a lot of subcontracting that you have to do just to do any job, right? Because you're not going to be able to do every single job on a set for video production. But in same vein, I'm sure there was earlier days where you were trying to do a lot of the jobs just to save money and to give yourself more of the income that was coming in. So can you talk about your mindset when you decided to start to subcontract and how that's evolved over the years of being in business?\n\nCole Heilborn (48:47): Sure.\n\nEmily Holland (48:50): I guess it's subcontracting and outsourcing for different things. I am technically an outsource, I would say probably for you, for the podcast,\n\nCole Heilborn (48:59): But\n\nEmily Holland (48:59): Then, yeah. Okay, so subcontracting and outsourcing.", "token_estimate": 450, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "47:07", "end_timestamp": "48:59", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "3c5cfc8c-c052-4073-9cf6-7e070dc40be1", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 26, "content": "Cole Heilborn (49:03): Sure. So I guess while I wrap my thoughts around my thoughts on that, maybe I'll just give the brief history lesson of what I've done. So at first, it started out just me hustling with a camera, doing any sort of job that I could. And I did that for a while, had some good jobs, had enough jobs that things were going well, but then you reach a point where either the job requirement is beyond your particular capabilities or you need a certain skillset like, oh, for this job I need a drone operator, or We need someone to design some graphics, and that's not within my wheelhouse. So I think everyone reaches a point where they know that they start needing help. And whether that's on the project specifically or if that's on a more ongoing support with other operations of your business, this is kind of an interesting question. (49:58): I feel like there's a point in a freelancer's career where they either, not that there's only two options, but you either stick with the freelance route and you are a hired gun, or you take that knowledge as a freelancer and then you start to evolve maybe more into a business or provide agency type services. And so maybe you yourself are no longer the person out shooting as much, or you aren't the person designing the logo, but maybe you're directing or you're the creative director, or you're taking on more of a producing role and you're hiring people who are hopefully better than you to do the work, and you're providing support in other ways. So I think it was a couple years ago when I kind of reached that point where I had done enough jobs, I had first kind of found what I wanted to do in the film industry, which was produce and direct. (50:53): And I knew, okay, everything else that isn't happy to do it, but I'm not good at it. And I would much rather get better at producing and directing and find other people who can help with those other roles. And then once I found that, once I felt good about that decision for myself, I realized, you know what? I really am interested in trying to build a business beyond just myself. I would love to make this bigger than just me and be able to provide more services and be really selective about how I'm interacting and what I'm doing in the business. And that's when I started to go down the path of trying to figure out how to do that. And that is a really interesting journey and a really gosh difficult process. And I think that really depends on the field and the industry that you are in. But I think that distinction between am I a freelancer or am I a business owner who's managing people? You reach a point and I think you have to kind of start to make that decision.", "token_estimate": 675, "speakers": ["Cole Heilborn"], "start_timestamp": "49:03", "end_timestamp": "49:03", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "19f48f5d-16fb-4bbc-8f78-0d944eb7d7c6", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 27, "content": "Emily Holland (51:51): Yeah. Yeah, that's really helpful. And I think there's all sorts of logistics that come with that subcontracting that you have to be aware of. And I'm sure I don't subcontract currently, but I'm sure tax implications as well. So one thing I wanted to just mention as we sort of wrap up a little bit here is also there's a lot of questions that freelancers are aimed to have, and we are not legal and or financial professionals as you can probably guess. And so there's a lot of resources out there now that can offer that to you. I would just say that having financial literacy around the things that are going to affect your business and just in general as a freelancer is really important. And even if you think you're not financially minded, I think it's important to at least understand the very basics of what you're going to need to understand as a freelancer. (52:46): Not to say that we can offer that here. However, I think most small business administrations, or at least in Boulder, we have the Small Business Council of Boulder. They have so many free resources. You can meet with lawyers and meet with accountants, all kinds of different types of people that have actual qualifications to talk about this stuff. And I know that Boulder is not unique in that. So there's definitely resources. So just look for small business resources in your area, and you can probably find free ones to get the sort of advice that you might need to get things like, should I be an LLC or a sole proprietor? Do I need a business license? Those types of questions are really important, and I just wanted to shout that out. I didn't know about that before I became a freelancer. Yeah,\n\nCole Heilborn (53:42): Yeah, that's a great point. I think the best thing you can do is just go find an accountant and have them help you with this stuff. And I think also there's a difference between an accountant and a tax accountant or like a bookkeeper and a tax accountant. You should make sure those bases are covered because you can really get screwed over if you're not careful there.", "token_estimate": 524, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "51:51", "end_timestamp": "53:42", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "0439a95b-0579-4941-86a3-a328156ae2b2", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 28, "content": "Emily Holland (54:04): Definitely. Another question around the outsourcing piece is maybe not outsourcing, but the idea of investing in your business too. So feeling when do you know when it's okay, invest back in your business? So I mean in things like professional development, like taking courses or programs that are going to benefit you, maybe going to conferences, did you start to do that right away to start to network, or what are your thoughts on reinvestment, not just in the subcontracting and outsourcing, but in the actual intangible stuff too?\n\nCole Heilborn (54:42): Sure. Yeah. I mean, I think investing for everyone looks a little different based on your own situation. I guess for me, how I've always thought about investing is what's the minimum amount of money that I can take from the business to still live a quality life where I'm not just eating Top Ramen,\n\nEmily Holland (55:00): Although that's great.\n\nCole Heilborn (55:02): Yeah, it works.\n\nEmily Holland (55:05): It gets calories in for sure,", "token_estimate": 256, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "54:04", "end_timestamp": "55:05", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "aedea5d4-f650-4353-856d-2627f1eb4622", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 29, "content": "Cole Heilborn (55:07): But what can I do with that money besides just paying myself? And so sometimes, in fact, for a long time, and I guess I still have this idea that I'm really interested in playing this in the long game and seeing where it goes. And so if that means keeping money in the bank account solely to pay myself in six months from now so that I can keep doing this, I see that as an investment. I'm investing in myself, and I'm investing in the advantage of time and hopefully what you'll learn through time and the opportunities that open up through time. That's kind of a long-term more nebulous answer. But I think even what we were talking about free work, does investing in a free project or a project where you're going to spend money on it, is that worth your time? And I think if it meets the needs where you're at right now, that's something to definitely consider because I think that's a form of reinvesting, updating that portfolio, expanding your skills, et cetera. (56:09): I think freelancers are probably pretty good at always working on improving themselves. You talked about classes and courses and all that stuff. I mean, that's stuff that I've always been interested in. So I think I've always been pursuing it, and I have always seen those things as investments or little seeds that you plant, and then who knows how they'll develop in the future. YouTube is an excellent resource that has so much great free material out there. There's also tons of great books. So I mean, I think I've lost track of your question, but yes, you should reinvest in yourself, but that doesn't have to be very complicated. It could just be saving money for next month.", "token_estimate": 421, "speakers": ["Cole Heilborn"], "start_timestamp": "55:07", "end_timestamp": "55:07", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "6324983d-b978-44ed-88f7-3a47ab821e3e", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 30, "content": "Emily Holland (56:49): Yeah. Okay. I like that because I think when we hear reinvestment, we're like, oh my gosh, we have to take every penny of extra money that we have and put it into getting the next best software or getting the next accounting software that we need, or piece of gear that we need for this. So I think that's a good call out, that it's like, just make it small increments. Could just literally be listening to podcasts and books and that kind of stuff first, and then as you feel more comfortable spending a larger sum of money taking the courses, that makes sense for you.\n\nCole Heilborn (57:23): Totally.\n\nEmily Holland (57:24): Cool. Well, I think we've essentially got through the questions that we were hoping to get through today. Is there anything that you want to wrap up with Cole?\n\nCole Heilborn (57:34): No, other than just thank you. I think this has been fun. I'm excited to get this out in the world. I'm also really excited for the other episodes that are coming out this month. We've got some very qualified individuals speaking about some awesome topics, so I just want to thank our audience and our listeners for, again, providing that feedback and allowing us to do this show.\n\nEmily Holland (57:56): Awesome. Let's do it.\n\nCole Heilborn (57:58): Awesome. Well, Emily, thanks for flipping the tables a little bit today. It was good. It was a little bit of an exhilarating experience. I've never felt so much adrenaline pumping through my veins, but I'm not really sure how to sign off because usually I ask people where to follow and all that stuff. But\n\nEmily Holland (58:16): Yeah, we'll follow Cole Backcountry Marketing podcast, or Cole or Portside Productions on Instagram. I'll do it for you, Cole.\n\nCole Heilborn (58:26): Okay.\n\nEmily Holland (58:26): Thanks everyone for listening.\n\nCole Heilborn (58:28): See you. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 518, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "56:49", "end_timestamp": "58:28", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "f82ec3e0-62bf-4d5d-8732-9fd57040a79e", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 0, "content": "Maari Casey (00:02): Again, it all goes back to how you start the relationship, managing expectations, putting together your documents clearly and just being okay, communicating over communicating. We feel a little bit like an imposter center. I'm not a real business. I'm just one person, and so we don't do all of those steps that a real business would do as far as contracts and legal and timelines and expectations, but it's important to really do it because if your goal is to continue to grow your business, these things need to be in place just to protect you.\n\nCole Heilborn (00:33): Welcome to the Backcountry Marketing Podcast. My name is Cole Hallborn and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast. This episode is produced by Port Side Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo, and today I'm sitting down with Mari Casey. She is the CEO and founder of UN Company. Mari, how are you?\n\nMaari Casey (01:16): I'm good. How are you?\n\nCole Heilborn (01:18): I'm doing wonderful. It's been a great Monday and I'm excited to wrap things up today with this interview conversation with yourself.\n\nMaari Casey (01:28): Yes, thanks for having me.\n\nCole Heilborn (01:30): No problem. Well, I'd love if you could give us a quick, quick introduction. Where are you located? What is Un Company? I've had the opportunity to connect with you a little bit before, but it sounds like what you guys are up to is pretty awesome, and so I'm excited to include you guys in our freelancer month of March. We've got an exciting topic ahead of us, but to start, could you give us a brief introduction?", "token_estimate": 507, "speakers": ["Maari Casey", "Cole Heilborn"], "start_timestamp": "00:02", "end_timestamp": "01:30", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "b6823e40-c3f0-4317-9ea5-49bd39cd4a34", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 1, "content": "Maari Casey (01:56): Yeah, yeah, thank you. Yeah, we are located in Raleigh, North Carolina, but we are really an office all over the place. We work with about three to 400 different independent contractors and freelancers all over the world. I built UN company after working as a freelancer coming out of design and art direction and advertising, and really what I've put on company together to be is a hybrid between a staffing company and a collective of freelancers, and we really focus on connecting both freelancers with clients for opportunities, so jobs, education, so career development and training, and then community, just connecting the larger freelance community together for resources and all the different things.\n\nCole Heilborn (02:38): So I guess I'm trying to think of what other companies or services out there sound similar to what you guys are doing and a site like Fiverr comes to mind and I realize that you're not what you guys do because you kind of explained some of the differences or Yeah. What's unique about your guys' model?", "token_estimate": 264, "speakers": ["Maari Casey", "Cole Heilborn"], "start_timestamp": "01:56", "end_timestamp": "02:38", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "82130103-fd94-4a41-aec6-8bd8c9c299db", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 2, "content": "Maari Casey (02:54): Yeah, so when I started it was really because I'd worked as a freelancer for some time and I kind of listed off all the different things that bugged me when I was working independently and tried to build a business to combat that, to really kind of get at each of those friction points. And so the way that we're different than a typical staffing company is we don't foster that race to the bottom mentality of pricing where it's like, who can do it for the cheapest? It's not a feeding frenzy. It's really connecting the freelancer or the team to the opportunity and letting them bid and price themselves based on what they know their business needs to run at. So we do our best not to get the middle of people's businesses. We're really set up to be a conduit of connecting the two parties, connecting the freelancer or the team to the client, and ideally everybody's connecting to the work they really love to do. (03:40): And so that's one of them. We work a lot with more senior level freelancers, although we do have a fair amount of junior and mid, and really it's what I wanted to build was build a resource for people to continue to grow their business from a sustainable standpoint, meaning get work that's up to their experience level, get paid correctly, get paid on time, all those fun things that you experience when you're working independently, which is chasing down payments and getting clients to communicate and all that different stuff. So the company we've built really kind of builds systems and services around each of those different things.\n\nCole Heilborn (04:14): Awesome. Yeah. And I guess how did you end up at the position where you wanted to start this company? What's your background?", "token_estimate": 434, "speakers": ["Maari Casey", "Cole Heilborn"], "start_timestamp": "02:54", "end_timestamp": "04:14", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "0d93cb7a-95c0-4e8b-86b3-c0e536124d75", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 3, "content": "Maari Casey (04:22): So my background is in advertising, so I worked in agencies for several years as an art director and I loved it and it was great. I just got to a place in my life where I needed more personal time to do different things. And so I got out of the agency life in about 2008 and started freelancing and loved it. The fact that I realized I could build a business, doing the work that I love with clients that respected what I did and then also have time to go for a run in the afternoon and take a yoga class and try other things was really eyeopening for me and I can't imagine going back. And so the more and more I worked independently, my business grew, I had a lot of people coming to me asking, how do I do this and how do I find clients? (05:05): And my husband kind of called me the freelance godfather for a long time, and I really enjoyed connecting to people and helping them figure out their business. And I just saw that there was a resource, there was a need for what I call a soft place to land where if I'm leaving corporate or if I'm leaving brand or agency, I know I can go to this one spot where I'm going to be finding great connections to solid clients who understand how I work, respect how I work, pay on time, value the work I bring, and then I could connect other freelancers who are building a career as an independent, and then I could also connect to resources on how to build a business and how to grow a business and all that stuff. And I'm a creative, so opening up a spreadsheet and having to figure out taxes and all the legal stuff around working as a business owner was really new to me and to me, I experienced where I was trying to find all those different things all over the internet and talking to this person who knew this person, who knew this person, and I really wanted to build one place for people to go where they knew that they could find a trusted and reliable resource.", "token_estimate": 484, "speakers": ["Maari Casey"], "start_timestamp": "04:22", "end_timestamp": "04:22", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "2f931452-4515-414c-a0f0-7b6d14c30937", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 4, "content": "Cole Heilborn (06:07): Yeah, there's a lot of questions around those topics that I feel like freelancers deal with frequently, and I guess just to have a better understanding what type of work typically comes through your guys' doors. You do work, they can do some stuff in the outdoors, but also beyond that as well.\n\nMaari Casey (06:26): Yeah, it's really all over the place, which is why I love it and why I feel like it's such a great challenging environment to work. And we have projects that can be a two hour project, and then we have projects that could be multiple years. Most of our clients, our clients, the verticals are kind of across the board. We have a lot of video projects and outdoor projects that are coming in, but we do web development, content creation, motion design, we do research and strategy. It's really, a lot of times it's just connecting the client to the right resource in our group. So the nice thing is the services that we've created and how we're working through projects is it's really, really able to take on super, super small projects as well as scale up to doing larger assignments and longer term projects too.", "token_estimate": 289, "speakers": ["Cole Heilborn", "Maari Casey"], "start_timestamp": "06:07", "end_timestamp": "06:26", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "eeccec84-ceba-4b1d-ab7f-1294644a1c1e", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 5, "content": "Cole Heilborn (07:09): Gotcha, gotcha. Well, I really appreciated what you said or how you described it. You said we're kind of that soft landing place for freelancers who are in transition or are trying to figure out what does their future look like as they get some footing underneath them. And I am thinking about our subject for today, which is this idea of management, client management on a high level. And I've got to imagine you've seen a lot of, well, I'm sure you've seen a lot, but I'm sure you've seen a lot of stories around just the challenges of managing clients as a freelancer, which is ultimately what it sounds like helps lead you to start your company and provide that place for folks. And so I'm really excited to have you on the show and we're going to kind of dive into this idea of client management and explore some different angles to it because I think you think about one of the main pieces of feedback we've received from freelancers is how do I find work? And I feel like that's a question that people ask all the time, but then let's say you get the job, then you actually have to deal with the client, you have to communicate with them and you have to deliver the thing, and that's all management. So I guess what have you experienced and what have your observations been around this idea\n\nMaari Casey (08:26): Around managing clients?\n\nCole Heilborn (08:28): Yeah,", "token_estimate": 350, "speakers": ["Cole Heilborn", "Maari Casey"], "start_timestamp": "07:09", "end_timestamp": "08:28", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "18c6301e-59e8-450f-9746-392e01791b42", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 6, "content": "Maari Casey (08:29): I mean, I think a couple different things, and I think a lot of times I always say when people go from corporate setting or say an agency setting to being an independent business owner or a freelancer, there's a little bit of amnesia that happens on both sides. So vice versa when they go back and you kind of forget what it's like to be internal at a company when you go out to be an independent. And then same thing when you go back from being a freelancer into a company, you forget what it's like to be a freelancer. And what that means is when we get into a situation where a freelancer's frustrated with a client, usually what I'll have them do is say, just remember this person has probably worked 60, 70 hour weeks for the last month. They're probably working multiple jobs, especially right now because such a shortage of talent. (09:11): People are probably worked really, really hard. They're probably managing multiple meetings that shouldn't have been a meeting. They're dealing with all those things that you left to be a freelancer for. And just thinking through a little bit of empathy on what they're experiencing goes a long way. And the same thing for clients. When clients are frustrated with how quickly things are turning or project management or something, I say these people are dealing with multiple clients, you are one of their clients and so understand that they're managing a schedule across the board. So a lot of times I think with just managing a client, it's just really almost thinking proactively for them and understanding where they're coming from. So just assuming they're overworked, they're probably underpaid, they're probably in a bunch of meetings and running back and forth and managing your one vendor of many and then just thinking through how you can help them get ahead a lot of those issues. And that usually goes a long way just because then the conflict does come up. If the client feels like you're kind of in their corner and you're understanding and listening to them and you're not jumping into that panic mode that we've all experienced, then they're usually a lot more forgiving when something does deadlines move or a timeline changes. So just kind of thinking through that part of it.", "token_estimate": 566, "speakers": ["Maari Casey"], "start_timestamp": "08:29", "end_timestamp": "08:29", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "c59069dd-ef65-44d9-a028-d05c65a52f60", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 7, "content": "Cole Heilborn (10:22): Gotcha. And\n\nMaari Casey (10:24): Is this, which is hard to do sometimes.\n\nCole Heilborn (10:25): Totally. Is this a challenge that most freelancers have or do you find that a lot of people have these skills developed already?\n\nMaari Casey (10:34): I think all of us have it at some point, depending on the client and how tired we are and stuff like that. I think the key is just to slow down and a lot of times, especially for coming out of agency, agency environments or working with agencies, there's that underlying panic mode vibe that we can get pulled into because of course we're service providers and we want to help them. We want to do a good job. So someone's panic can get you panicked, then everyone's panicking. I think the key is just to take a deep breath, especially when you get in a situation that's maybe getting a little intense, take a deep breath, walk away and get some perspective and say, okay, what do I need to do right now to help us get through this situation or to move the project forward, or how can I reframe this a little differently? And that goes a long way. I think when people jump into the panic mode and it causes more panic, then nobody benefits. At the end of the day, the freelancer is usually pushing work out that they're not happy with and the client's probably stressed out and not seeing all the things. So I think just take a breath, slow down, try to slow everybody down, be that calming presence in the room or on the call.\n\nCole Heilborn (11:37): Sure. So of all the different freelancers that you guys work with, how common is this challenge of managing clients? Is this prevalent throughout all of the verticals and all of the industries? Are some people really good at it, are some people, how difficult is this to do\n\nMaari Casey (11:58): When you say some people, you're meaning some clients are being better at managing than others.", "token_estimate": 479, "speakers": ["Cole Heilborn", "Maari Casey"], "start_timestamp": "10:22", "end_timestamp": "11:58", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "0ed29653-9a11-497f-86a0-6d809ba171e6", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 8, "content": "Cole Heilborn (12:03): As a freelancer, I feel like this takes skill and it takes practice and it takes learning. How many freelancers do you deal with? Do they struggle with some of these things? I know this is something that we deal with frequently is how to best manage the client and serve them, but what's that from your perspective?\n\nMaari Casey (12:24): I think if you're starting out and you're relatively new, especially when you're coming out, maybe coming out of a creative agency environment, it is a little bit tricky to figure out how to do that. So it depends a lot of times on your just seniority and how long you've worked because you get used to having those meetings and possibly leading those meetings. If you're coming out of an agency environment as a junior or even a mid-level, sometimes you just haven't had that kind of exposure to run meetings, set expectations, talk through timelines. So if you haven't had that experience, then it's something you almost have to learn as you're going through things. And I see that usually when you have somebody come in who's just starting out as a freelancer, that's usually something we're aware of is like, okay, let's talk through how to set up expectations and how to run meetings and how to get ahead of it. So it really depends a lot of times on the experience they have coming into working independently, but some people are just better inclined to it too. Some people are used to, if they've been in leadership positions, even if it's not in a job, then sometimes they tend to be a little bit better or if they're coming from an account management role or something like that where they're used to leading in project managing.\n\nCole Heilborn (13:28): Gotcha. And so let's imagine the perfect situation, the perfect world where the client management side of the relationship is going super well. What does that look like or what does that feel like?", "token_estimate": 481, "speakers": ["Cole Heilborn", "Maari Casey"], "start_timestamp": "12:03", "end_timestamp": "13:28", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "5666f8d4-98df-43c3-8803-b0fc5ce570b7", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 9, "content": "Maari Casey (13:41): Well, okay, so the perfect way, I'm not even say the perfect way to run a project, totally different for everybody, but so I think the main part of it is expectation management, and usually when there is conflict in any kind of project, it's usually because expectations aren't being met and they haven't been really clear. So setting up a really clear SOW, here's the scope, here's the deliverables, here's the timeline, here's the budget, the three legged stool scenario, making sure those are really clear and reading through it again, having somebody look at it and be like, where is the potential confusion? Because it's really easy to miss that. It's really easy to be like, and here's the deliverables. Okay, what has constitute done? Is there a number of rounds that you're agreeing to before? It's a scope creep situation and it can feel a little bit, at least it did for me. (14:32): It can feel a little bit like judgy or non-trusting when you're like, oh, well maybe I'm going to put a kill fee in here, or I'm going to define milestone billing and what that means. But it's honestly, it's important because it's a CYA for you. It's also a CYA for the client. They can go back to that scope and say, you know what? You agreed in the scope to two rounds of revisions and we've only done one round of revision. That means I get another round of revision. So it's really nice to put all those things in paperwork and it feels sometimes a little bit too professional, like I'm being too fancy, but it's important because it will come back to you if you're not outlining those details clearly. So I would say just have a really clear scope of work, a really clear deliverables, really clear timeline because timeline can change the scope. (15:16): We've all been in situations where the timeline was a month and it became three months and then it became four months and it changes things. So being really clear about when timelines are set and then what that estimate and budget includes and where there might be room for a stock fee or an overage if I'm charging for talent or any of that kind of stuff. So as clear as you can be about those things, the better you'll be in the long run. And then when you get into a project before you start a meeting, and if you're like, okay, this is going to constitute round one, just be really clear, Hey, here's the agenda for the review today. This constitutes is the first round of review. Be really clear so that you can look back to your contract and say, remember we did that call. (15:56): That was the first round. The clearer you are, the better you'll be. And there's a Brene Brown quote that is being clear is kind and being unclear is unkind, and there's a reason why It's like when you're not clear, it leaves room for that miscommunication and missed expectations, and then all that icky stuff happens afterwards where you have to be like, no, I meant this. So being as clear as you possibly can be all the way through being really, really transparent with timeline feedback, expectations on the client side. So I'm giving you two days to send me feedback. If it goes longer than two days, it might push the timeline, which might change the overall project scope. So just being really clear where those things are. So a lot of times as creatives, we think we're communicating really clearly, but it's kind of soon as we're communicating in our head or to our friend. So putting it in an email, putting it in a document so you have something to go back to is really essential.", "token_estimate": 890, "speakers": ["Maari Casey"], "start_timestamp": "13:41", "end_timestamp": "13:41", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "dfc1b753-10f8-4294-bccf-e40f5e9d42ef", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 10, "content": "Cole Heilborn (16:51): So it sounds like everything that you just talked about starts with expectations and then being able to communicate around them. What constitutes expectations? I mean that's everything from deliverables to office hours. What are the other things that are in there that maybe aren't as common to be considered?\n\nMaari Casey (17:12): Yeah, I mean it really depends on what's important to you. You mentioned office hours. I think that's great to bring up expectations obviously include all the scope related items, so budget, timeline, deliverables, but also include we have a response policy, we will respond back to you within 24 hours within the business days, so we're not going to respond on a Saturday. So setting those expectations and boundaries upfront is super important to do because otherwise you're going to end up in a situation where the client's texting you on Sunday and expecting to get feedback, and it's not a healthy way to run a business. It totally depends on what is important to you to communicate, but expectations and communication all the way through will save you at the end of the day.\n\nCole Heilborn (17:59): Are there any expectations or things that you try to set or encourage other people to set that aren't super obvious or things that can really set you up for success with the client?", "token_estimate": 336, "speakers": ["Cole Heilborn", "Maari Casey"], "start_timestamp": "16:51", "end_timestamp": "17:59", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "ea0be0ac-532b-44e8-a996-0e6c3cd95e5e", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 11, "content": "Maari Casey (18:13): Yeah, I think boundaries. I mean, you brought it up with the office hours. Boundaries are so important, and I think especially when we're starting out as independent freelancers, boundaries is one of the last things that we think about because we're just trying to get as much work, and I was like, yes, I will drive by your house and drop off that drive. I don't care if you live 500 miles away, I'll be there. You tend to sacrifice your own time because you don't quite know what it's worth yet. But I think setting boundaries early allows you to really build a business that's successful because it's hard to know how much your time is worth when your time is readily available for free to everybody. So setting up boundaries as far as office hours, response time, super key. Even if some people charge rush fees, if you're asking me to work through the weekend, that's no problem, but it's going to be this. Or if you're asking me to drop what I'm doing and turn something around and 24 hours, it's going to be this. It totally depends on what's important to you and how you want to run your business, but I think setting up boundaries. I don't want to receive text messages on my personal cell phone. You can email me, you can slack or discord me, but I'm not going to respond to a text message. Those types of things I think are really important.\n\nCole Heilborn (19:19): Interesting. So coupling expectations with scope of work, which are kind of one and the same, but I feel like it's a different type of expectation. You mentioned it earlier, but scope of work is super crucial because that defines what you're going to do and how much you're going to get paid for it. I think a term that everyone's familiar with is this idea of scope creep, but could you define what that is and the problem that many freelancers find themselves in around scope creep?\n\nMaari Casey (19:50): That's what I wanted to be for Halloween this year, and my husband thought it was like, no one's going to get it.\n\nCole Heilborn (19:55): I think it depends what party you would go to, but that sounds pretty amazing.", "token_estimate": 531, "speakers": ["Maari Casey", "Cole Heilborn"], "start_timestamp": "18:13", "end_timestamp": "19:55", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "2d9e4c4c-c769-444a-9313-68a7da7fc8f7", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 12, "content": "Maari Casey (19:58): I was like, you can be the kill feet, I'll be the scope creep. He was like, no, that's not. Yeah, I mean, scope creep is a real challenge and it's especially tough if you don't know how to handle it because what happens is usually if you've manage expectations clearly, then you're not going to run into that as often, but as you're learning and setting up your contracts, there'll be instances of that and honestly, you'll have clients who you've worked with for years that'll do that just because they're like, oh, Cole's my buddy and he's fine. Slide me some extra deliverables. And I think all you need to do is just be really clear, go up to them. I always say use it as an opportunity to upsell to your clients and say, Hey, I received your email about these additional changes or this additional round can totally do that. (20:45): Here's a timeline to get that done for you. And then now that we're making that change, I can go ahead and amend the contract that we currently have to include that plus the timeline, plus this additional fee, which I'm estimating as blank. Let me know if that sounds good for you. I'll go ahead and send that over for e-sign or whatever. So I would go ahead and just put that all into one thing. This is already happening and here's how I'm going to make it easier for you. I'm going to go ahead and amend our contract, send it over through DocuSign and we can get this rolling as opposed to making it feel like it's an awkward conversation, I would just say expect that they know that and if they push back and they say, oh, I'm sorry, I didn't realize this was a scope group, I need to go and get approval. (21:22): You can say, sounds good. I'll have this contract ready to go amended for whenever I hear back from you. Or if they do push back and they say, well, can we go ahead and do this under this SOW? Then you can say, actually no, this is outside of the scope. And you can see based on what you've done, if you can adjust what you're working on to include that and pull something out, we can adjust the current deliverables list to include this. If this is now a priority, it totally depends again on how much you want to work with the current contract, but I think once you start agreeing to things that aren't covered in the scope, then that's going to be happening more often. So I would just cut it off, no judgment. Again, think about this person's super busy, they don't realize it, they're just trying to get their stuff done and I appreciate people who are trying to get things done. I'm going to make it easier for them and just kind of go in with that attitude and then it won't be weird.", "token_estimate": 668, "speakers": ["Maari Casey"], "start_timestamp": "19:58", "end_timestamp": "19:58", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "4aa015f3-5cf8-42c5-bbc3-547114252f1c", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 13, "content": "Cole Heilborn (22:11): Gotcha. Is there a way to make a scope of work document that is a hundred percent watertight so that there's no room for misinterpretation or confusion?\n\nMaari Casey (22:26): Probably not, because there's always a few things that are going to come up, but I mean not with scope creep because people will add things on just at the end or I think that the question that always comes up is what constitutes round one, round two, round two didn't really quite deliver all the things, and that's really for you to define as clearly as possible. And then if you feel like it's being pushed, pushed or taken advantage of, then you need to speak up. But I would just, again outlining what's the goal? What is the goal for this project? What does success mean? What is this is done, put it in the can, signed, sealed and delivered, what does that mean? And that's usually a conversation that you should have probably even before you write the SOW, that's your intro call where you're asking about the project, what does success look like for this project for you guys? (23:16): And then clear timing, when is this going to be delivered? When can we expect to review? I would always send over a timeline that's like, here's based on your goal end date, here's my timeline as it works within my schedule. Don't put that off on them. Then they're going to be like, they're going to squish it into three days. Give them a timeline and timeline and based the timeline, here's when check-ins are going to come and we're going to check it on Wednesday. We're going to show you all the work and then we're going to email you over the PDF. We're going to expect feedback by Friday. And then you can say, again, if we don't get feedback by Friday, if it gets pushed in the next week, it could adjust the timeline just to let you know, so timing, budget, rounds of revisions, how many rounds are you going to agree to, and then a clear deliverables list. (24:00): And sometimes you can also include what might constitute a scope change or sometimes you can put in like, okay, if you need extra cuts or something, if you need a couple cutdowns, it's going to be like this per cutdown, like a little la carte menu separately. But I would always put all those things in there and then if you are doing milestone billing, if you're billing up front because you need to cover talent or location or all the things, I would put all of that in the contract and say, here's what I'm going to invoice you. Here's what the invoice constitutes the first 25% or whatever, it's going to be expected upon receipt or net 30, blah blah, blah, blah. So I would put all that stuff in the SOW.", "token_estimate": 669, "speakers": ["Cole Heilborn", "Maari Casey"], "start_timestamp": "22:11", "end_timestamp": "22:26", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "cff70ed5-da63-4e88-bf1f-14a7eb64bc3a", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 14, "content": "Cole Heilborn (24:40): Gotcha. Your example of revisions and what constitutes a revision being done is I feel like one of those gray areas where it can get kind of sticky, as you said, maybe the freelancer did what they constitutes is the first round, but the client's like, well, did you really do it or It wasn't done how we had hoped, so can we have a 1.5 revision round in between? I realize a lot of this comes down to nuance and communication, but what are some ideas or best practices in a situation like that?\n\nMaari Casey (25:18): Yes. The old 1.5. Yes, I've heard that. I mean, I think part of that's also when you have your new business meeting where you're getting to know the client and you're say, Hey, you bring up all those questions at the beginning, it's like, here's what success looks like. Here's what I've experienced. When I do do a meeting where I'm doing a review, we'll talk about this is the review meeting, number one, here's the expectation. I always set agendas for my meetings just so they know that it's really clear, here's what my role is, here's what your role is, and then that way at the end of the meeting you can say, okay, cool. This is round. This is round one, good to go. And then when you send a follow-up email outline all the stuff that was happening in that meeting, and we'd be like, we're going to go ahead and send the first invoice by first amount looking forward to your feedback. So you're giving them opportunities to say, oh wait, we don't really feel like this is a solid round one or whatever. But hopefully since you've outlined it clearly that it won't be a big issue. If they come back and they're like, well, it's round 1.5, then you can say, well, we don't, no, actually this is round one. That's when you need to push back and just stick to you and say, we've covered all the deliverables for round one. We had a feedback session, we received your feedback, so we're going to move into round two.\n\nCole Heilborn (26:28): Gotcha. In an instance like that, do you always send a follow-up email recapping a meeting, the CYA email, or do you just leave that up or do you just end the conversation and then not follow up in a written format?", "token_estimate": 550, "speakers": ["Cole Heilborn", "Maari Casey"], "start_timestamp": "24:40", "end_timestamp": "26:28", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "9de6d129-03bf-4443-a157-765969a384b8", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 15, "content": "Maari Casey (26:44): I typically do, and I would recommend it just so that again, you had the meeting where you're like, here's what we've done. Here's the work, here's where we are. And then you've said at the end of the meeting, Hey, we're going to expect to see feedback on Friday in the PF or notes and whatever, and then send the follow up based on what you heard in the call. And then again, we're going to expect to see feedback on Friday. It's just a good reminder. Again, most of the clients that we work with are usually pretty busy, and so it just helps them to be like, I'll check in on Friday morning to see where we are. Again, this is also, I think one of the questions we had talked about was who's managing who. And I always find it's more successful for a longer term relationship if the freelancer is really taking ownership over managing the client too. Because again, just thinking about them being super busy and I like to take control over situations as much as possible because then I can help to manage it on my schedule and my terms. So if I can say, okay, well I'm going to follow up with you, then it's putting me in a driver's seat as opposed to me sitting back on Friday and being like, I wonder when they're going to email me. It's like, let me email you.\n\nCole Heilborn (27:51): Interesting. And I imagine that mentality really starts from the beginning of the project if you're going to manage the client or if they're going to manage you, and ultimately, I guess that perspective is maybe small, but sets a big impact for the duration of the project.", "token_estimate": 396, "speakers": ["Maari Casey", "Cole Heilborn"], "start_timestamp": "26:44", "end_timestamp": "27:51", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "9abf3c8c-8362-4314-926d-a9710549da66", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 16, "content": "Maari Casey (28:06): Yeah, it does. They know that you're in control. I think I've worked on both sides, so I've experienced both sides of it and sometimes when I was working with freelancers, there's that little bit, I can't see what's happening. Are you working? Do you have a question? So just taking that, giving them a peace of mind to be like, yep, I'm working if this is in control, you got a timeline. It just allows them to honestly back off of you and let you do your job and lets you do your work because checked that box for them like, yep, cool. Reach out to me. We're on schedule. Things are coming through. It maybe takes you five minutes to write an email once a week to let them know the progress of the project, but then they can leave you alone all week and you're not having to worry about managing things that are in panic mode. So to me, it's a great thing to do because it gives me space as a creative to go in and do my job because I've already checked the box with the client that things are humming along in the background.\n\nCole Heilborn (29:01): Sure. Will you sit down every week and run through your list of clients and send out status updates and then continue on with your day or your week?\n\nMaari Casey (29:10): It depends on the size of the client and how long we've worked with each other, especially with new clients, just like what's happening a little bit. We'll check in more often just to make sure they feel solid and that things are working and processing. But with our larger clients, we might check in once a month. We might check in at the close of a project or the start of a project, or if we're running our OnDeck service and we set up a whole team that's working, we'll probably check in a week one or two just to see how everybody's working together. But after a couple of years, everyone's like, okay, on companies doing their things, then we won't bug them as much, but it's really just giving them that security that they know things are happening and that we've got the ball and we know what we're doing.", "token_estimate": 515, "speakers": ["Maari Casey", "Cole Heilborn"], "start_timestamp": "28:06", "end_timestamp": "29:10", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "10c6c8ef-bf0f-4498-a0db-462b3f298e9a", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 17, "content": "Cole Heilborn (29:57): Gotcha. Okay. Yeah, makes sense. That's something that I have wanted to implement in a better format is a weekly, whether it's Monday or Friday or any day, just sitting down and saying, okay, hey client, here's where things are at. Quick update for you. We're still waiting on this or\n\nMaari Casey (30:14): Yeah, and automation is your friend. I'm a big advocate for automation. We use a couple different tools, one of which is automation and emails and Zapier, and you could do that by just setting up a really awesome timeline and then once a week it'll, it pings the client, here's where we are in the progress, here's the timeline, or just checking in if you have anything, shoot me an email back if you have any questions. So just letting them know that you're paying attention to the project. You might not even hear back from them, but it just kind of drops into their inbox. It's super easy to do. And I was like, what are the things that you can automate to help again, alleviate your time to do your job? It's amazing, and there's so many fabulous tools out there to use.\n\nCole Heilborn (30:57): Yeah, so dive a little deeper there. Explain that. How does that work? How does that process work?", "token_estimate": 307, "speakers": ["Cole Heilborn", "Maari Casey"], "start_timestamp": "29:57", "end_timestamp": "30:57", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "8559cd26-b6ff-471c-b992-c553f3f78b97", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 18, "content": "Maari Casey (31:02): Well, we have a lot of tools that we use. So we use Asana as a project management software, which I'm a huge advocate for Asana. Super easy to use, very user-friendly. You can use it deep dive and do Gantt charts and all the things. You can go as crazy as you want it with it, or you can use it pretty simply, which is what we kind of use it for. We use it for a lot of internal management for internal projects, and then we use a couple different tools for just managing our external vendors that are just project management that we drop the project in. It's more of a contract, here's the contract, here's the scope of work, and they can review it and sign it. And then we use active campaign for our automation, large automation and email platform where it's people sign up. (31:46): Once they're in there and they're in our flow, we can drag them into different buckets and it'll send them emails regularly just to check in. And that's a really great resource because you can go back into that person's account and see which emails they've opened and which emails they've been sent. So it's a cool tool to see which of your clients are more engaged and opening emails and paying attention. And it's nice if everything's in one little spot, so it's super, super clean. You're not digging through your inbox. I'm a digital hoarder, so I have a really hard time throwing and organizing my emails. So I like these automation tools. It does that work for you? So we use ActiveCampaign, we use Asana. We use a vendor management tool called Work Suite, which is wonderful. We also use Zapier, which kind of connects a lot of our dots. (32:33): So Zapier is this kind of InBetween tool. I should have my operations talking through this better. But basically when someone does something over here, Zapier will connect that, say they sign up for our email campaigns or email marketing stuff, Zapier connects that to our active campaign and puts them into active campaign, or it also connects to Discord and Slack and pings us on Slack and says, Hey, you just had a new person sign up. Here's their information. So then we can respond to them really quickly. They do that with, whenever we get a new job, we get a ping through Discord or a Slack that a new job has come in, and then that way we don't miss those things that are happening on a regular basis in the background.", "token_estimate": 598, "speakers": ["Maari Casey"], "start_timestamp": "31:02", "end_timestamp": "31:02", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "f3b35cfc-a4e6-4d91-8852-cd4d891fb090", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 19, "content": "Cole Heilborn (33:14): Interesting. Could you super\n\nMaari Casey (33:16): Crazy.\n\nCole Heilborn (33:17): Zapier is a super powerful tool and it makes a lot of the paperwork admin work so much quicker if you can take the time to link everything together. Do you guys use Asana and Zapier to send out client updates? Let's say you finish, let's say you finished pre-production on a project, does that automatically and you click that out of Asana, does that automatically send an update to a client or how does that set up?\n\nMaari Casey (33:46): Since we are not, since uny is really, we're just a conduit between freelancer and talent and clients. We're not managing the projects for them. We're not their project managers or their creative directors. We're really just connecting, say videographer and client for projects. So we let them use whatever PM software or tool that their business utilizes. What we use to connect our clients just to check in and our freelancers is we use active campaigns. So our freelancers will get emails at least twice a month, and then they'll get regular check-ins for like, Hey, put on your time sheet, what's going on? And then for the clients, they'll get check-ins on projects where they can click a form and go through and send us a note or a review. But we use active campaign for both sides, for clients and freelancers.\n\nCole Heilborn (34:28): Gotcha. Interesting. Yeah, I feel like project management tools, they can be really fun to geek out over and explore all of the features.\n\nMaari Casey (34:39): We do that regularly. We get new tech, we get new tech updates once a week, something new will come through, we'll be like, Ooh, let's check out this. So then our tech stack will get very, very large and then we'll start to be like, oh, we don't need these anymore, and then we'll add more. So it's kind of an ongoing joke that we're adding a new tool or tech or a thing to try out every single week.\n\nCole Heilborn (34:58): Are there any other tools that you would recommend folks looking into if they're trying to find just run of the mill project management options?", "token_estimate": 529, "speakers": ["Cole Heilborn", "Maari Casey"], "start_timestamp": "33:14", "end_timestamp": "34:58", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "a3c74e70-36da-4826-ba11-2822a597f2b9", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 20, "content": "Maari Casey (35:07): Yeah, Asana's great. Haven't used Monday, but I've heard Monday's pretty good. I mean, you can honestly set up, depending on how complicated you want to get, you can do a lot through Google. I mean, the Google Suite has a lot of tools and resources, just spreadsheets and Google tasks and that kind of stuff. So it depends on how deep you want to go. But yeah, I mean Asana for me has been the simplest piece of software that I've used for this.\n\nCole Heilborn (35:35): Okay, awesome. Are there anything in particular that you look for in a project management tool when trying to decide, because hundreds of them out there.", "token_estimate": 161, "speakers": ["Maari Casey", "Cole Heilborn"], "start_timestamp": "35:07", "end_timestamp": "35:35", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "0021416e-3291-46e8-bdbf-8a7bb447ba84", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 21, "content": "Maari Casey (35:44): Yes, yes. There's a lot. I mean, for what we use it for, because we're just doing managing internal projects and our content calendars, it's really simplicity and ease of use and ease, I guess ease for people to jump into. So we pull in freelancers and contractors to work for company internally. We want the tool that they jump into to be really easy for them to pick up in an afternoon. Like I said, a lot of them, I mean, you could use Smartsheets and you can get into doing Gantt charts and you can get into doing waterfall timelines and all that kind of stuff. And it really depends on what works for you. I mean, it comes down to the importance of project management is knowing when things are due, when you should be working on how to manage your time and how to check in. (36:24): So I would just start by even just taking a look at a calendar. And it also really starts with how you scope out your projects. You should have a good solid idea of how much time is going to take to do a project and giving yourself space for things to go wrong or to change so you're not just jamming yourself up and then get into a Google calendar and just build out a timeline right there and just start looking at it like that. And that's probably the first step. I mean, I didn't start using probably project management software until a couple of years into my business, probably should have used it a little earlier. But just the basics is just getting a really clear idea of how much time you want to spend per week, how many billable hours do you want to put in, and then how do you scope your projects against a timeline?\n\nCole Heilborn (37:05): Yeah, well said.", "token_estimate": 420, "speakers": ["Maari Casey", "Cole Heilborn"], "start_timestamp": "35:44", "end_timestamp": "37:05", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "f0ade599-6d15-48ec-904c-dce4a148ddcf", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 22, "content": "Maari Casey (37:06): Because sometimes you don't want to work 80 hours a week. That's why you got into being independent. So that's always the first thing too when I work with new freelancers is it's that feast or fam, it's like they're either crushed or they're absolutely panicking. They have no work. So figuring out a sustainable business from a time perspective goes to how many hours do you want to work per week? How many hours are you okay working when you get busy and then building out your windows and your timeline, looking at it from a longer perspective as opposed to like, ah, panic.\n\nCole Heilborn (37:39): Yeah, yeah, yeah. No, that's very, very common it seems like unfortunately. So I'm curious if we could talk a little bit about conflict and dealing with clients through conflict. You've kind of talked about it a little bit and obviously some of these things we've discussed. If you're communicating well and you have a good SOW document, those things help significantly when it comes to managing conflict. But I feel like one of the main problems with conflict with a client is that you need the client to be on your side because they're the ones that's paying for you, but you also need them to respect you. And so at some point you do have to push back, but being playing good cop or bad cop at the same time sometimes can be a little intimidating. You are one person. I guess, what are your thoughts there? Because inevitably conflict does arise and you have to figure out how to work through it.", "token_estimate": 381, "speakers": ["Maari Casey", "Cole Heilborn"], "start_timestamp": "37:06", "end_timestamp": "37:39", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "42233486-d2eb-434e-a397-6c5bbb048657", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 23, "content": "Maari Casey (38:40): Yes. I hate conflict. It's one of my least favorite things. There's a great book that I read early on called Crucial Conversations. I highly recommend it. It just talks about managing those. There's a great book on negotiations too, and I think that those are really important things to learn how to do. One of the first things I think I would recommend doing, and I still have to remind myself of this, is even though you're possibly a one person business, you need to separate yourself mentally and take a mindset of like, I am Cole. I work for blank. Or I am Murray. I work for company. And separate yourself from the business so that you can make better decisions of what's best for the business. If your goal is to run a business for as long as you want to work, then sometimes you're going to have to make decisions or calls that maybe Mari would feel really uncomfortable making because I'm a nice person and I want everyone to be happy, but it's better for UNY if I make this call. (39:34): So it's good to do that because it allows you to have conflict conversations and negotiations from a point of view that's not emotional. It's like, sorry, this is company's policy is blank. It's not personal, the policy of the business, and I want the business to be successful, so I'm going to back the policies. So it's good to just mentally separate yourself across the board for a lot of things, finances, all that stuff so that you can make decisions independent. It's easier said than done because of course you are your business and your business is you. But when I get into a situation that's a conflict or difficult, I'll sit down and I'll be like, okay, what is the policy that we're following? What is best for this business? Even if it makes me uncomfortable? So that's the first thing I would suggest doing. And then it's really putting everything on the table. (40:21): If you're getting into a situation where you, maybe you're negotiating a scope creep or the client comes back and is unhappy with the work, then I think you need to look at what's the longevity of the client? Is this a client that's relationship that's really worth protecting? Or sometimes they're just bad clients and sometimes there's bad freelancers, bad clients, or in bad situations sometimes there's just people who are in a spot that's in a tough spot. So I would look at all of those different things and evaluate based on your relationship and history, maybe even based on the network of that client and how it would affect it, and just take a look at all those things. And then again, I always try to lean into how can we make this work? So if I get into a situation where it's a conflict situation, I always go into it the mindset of how can we make this work? (41:04): Can I adjust this way? Can you adjust that way and just talk about it really directly and then just approach it that way. And I think most of the time you can work things out sometimes when you can't and you have to walk away. I think it's deciding again, is this worth really just holding onto, am I going to walk away and not get paid and be upset, but I'll survive it? What I've seen a couple times, which is dangerous is somebody holding footage, they're not going to get paid or coming back and damaging footage or bashing the client after thing. I think there's ways to do it cordially where it's like, okay, well it wasn't a good fit for us and this is just kind of keeping it more one-to-one versus blasting it out on social media and that kind of stuff. That never reflects well on your business, even if it's true. (41:59): But I would say always approach those conversations as honestly and directly as possible. Let's sit down. I've noticed that you've been frustrated with this type of work. How can we address this? What can I do to fix this? Or if you're in a situation where I've had some situations where clients are being really maybe damaging, going to them and saying, Hey, these are some things that are not how we operate. We don't call the freelancers at 2:00 AM or we don't save things that are hurtful, but honestly, most of the time, 99% of the time, those things never come up. So it's like that 1% of the time when they do, it's always difficult. It's always the thing you're like, Ugh, self-employment iss great.", "token_estimate": 1082, "speakers": ["Maari Casey"], "start_timestamp": "38:40", "end_timestamp": "38:40", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "88625e4a-99dd-4324-bba4-f01a0a7daa14", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 24, "content": "Cole Heilborn (42:42): So you mentioned something like it's very easy to disassociate separate yourself from the company, wear two different hats, and that helps you make decisions. And it sounds like you can kind of, I'll say blame, but you can put things on the company and say, well, this isn't the company's policy. Even if personally I would love to be able to do this for you, if it's, I mean you say policy, it's some written rules somewhere that sounds very fancy. What if I'm in a conversation with a client and I have never come across this circumstance before, but I'm like, I don't know how to respond to this. It feels a little off, but I haven't ever considered this before because I think we find ourselves in those situations frequently or maybe, hopefully not frequently, but inevitably at some point.\n\nMaari Casey (43:30): Yeah, I think it's okay to walk away and think about it. Sometimes the tough part can be feeling the need to respond in the moment and defend, and then you can kind of feel the vibe changing. I think it's okay to say, this is interesting to look at. Let me go back and noodle a bit for a little bit and I'll follow up with you and we can send an email or I'll follow up with another phone call, but give yourself some space to take a step back and look at all those things. Look at the viability of the client, look at the relationship you have, look at the work that's been done. But sometimes you just can't do that in the heat of the moment. I have a public speaking coach, we're talking through breathing. But a lot of times when you get in those situations, conflict situations, you stop breathing because it's like a fight or flight mentality or body takes over and it's like, I must run away and defend. You stop breathing. So it's interesting because your brain actually starts to shut down a little bit, not taking deep breaths. So it's good just to say, you know what? I think this is a good thing for us to look at. Let me take a step back and get back to you in 24, 48 hours with a follow-up. And that's totally fine. That's a good way to get back and actually reflect on it without having to make a quick second decision.", "token_estimate": 544, "speakers": ["Cole Heilborn", "Maari Casey"], "start_timestamp": "42:42", "end_timestamp": "43:30", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "53b430d9-7b00-4894-9c4f-7a766d8c300f", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 25, "content": "Cole Heilborn (44:40): Yeah, taking time, maybe going on a run or going on a bike ride.\n\nMaari Casey (44:45): My daddy used always say, take a lap. Go take a lap.\n\nCole Heilborn (44:49): Yeah. And let's say you get to a scenario where the client isn't just a good fit. How do you deal with that?\n\nMaari Casey (44:59): That's a hard question. I mean, it's okay to say just that if you finished a project or if you haven't been a project and it's over. Firing a client is one of the hardest things I think to do. But I would just be really direct. I'm kind of a fan of being as authentic and honest as possible. So it was sending an email and saying, while we started this relationship together to do this project, we had a line goals. Some things just got expectations changed. Or sometimes things aren't a good fit, which is the honest truth. Sometimes two great people can come together and it's just the working relationship doesn't work out. It's no harm, no foul, it just doesn't work out. Sometimes budgets aren't aligned. Expectations aren't aligned, and I would just be direct about it. It, it's just not a good fit to work together. (45:46): We'd love to resolve this project, finish on a high note, whatever it might be. But I would just go direct at the problem. And that's usually the best way to resolve it. It's when you feel uncomfortable. I've learned When you feel uncomfortable, just lean into the uncomfortableness, just be uncomfortable for a little bit and just push through it. And that's usually the best way as opposed to avoiding and emails, and I'm not a fan of emails and text messages to resolve conflict. I think that's super dangerous ground. So I would do a face-to-face or video call or a phone call and just resolve it, which everybody hates because everyone loves just to send it and hopefully it lands, but it's a lot quicker just to get on the phone and be like, Hey, you know what? This just isn't working out and I know you do a good business. I know I run a good business and I want us both to be successful, so let's figure out a way forward so we can finish this up and wrap up a relationship at the end of the day.", "token_estimate": 539, "speakers": ["Cole Heilborn", "Maari Casey"], "start_timestamp": "44:40", "end_timestamp": "44:59", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "dbf5e9c2-243d-4e24-96c7-f07b5b1593d2", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 26, "content": "Cole Heilborn (46:43): Yeah, it's tricky though. If you're in a small industry and you're working with a client who has a lot of connections, the last thing you want to do is tarnish your reputation or make them look bad, or trying to protect that is tough.\n\nMaari Casey (47:01): It is. And that's where kind of evaluating the relationship and their network and how that's going to work is super important. I've never been in a situation where it's gotten into signing documents and we're not going to talk about this. I've never gotten into that kind of a situation. I have gotten into situations where there hasn't been payment, but I mean, I think going directly at it and usually having those conversations early helped to remedy that. So it's like, Hey, I noticed that you're unhappy or things are getting awkward. Usually the earlier you can do that, the better. Waiting until it's a huge fire and everyone's freaking out and it's anger is probably the hardest place to be. So if you can start taking steps when you notice things are kind of going off, then at least you'll probably put out the fire before it becomes huge.\n\nCole Heilborn (47:52): Right. So you mentioned another topic that since you've mentioned it, we should probably look into this idea of not getting paid. How do you deal with that?", "token_estimate": 328, "speakers": ["Cole Heilborn", "Maari Casey"], "start_timestamp": "46:43", "end_timestamp": "47:52", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "e5dce698-cc74-41b5-b45e-c982d10506b5", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 27, "content": "Maari Casey (48:01): Yes. That is so frustrating. And I mean, it can ruin your business. It can ruin your business. It can ruin a lot of relationships. That's one of the things I wanted to do with in-company was when we work with contractors and freelancers, we pay everybody net 30 and we manage the back end of chasing down payments and very good pay periods. I was like, as an independent business owner, I still need to pay my mortgage on time and my coworking space lease and all the things. So getting paid regularly, super important. And we should, the few times that this has happened for us and for me, and it's very few because again, you should have a pretty solid understanding of who your client is before you jump into a project with them, you really have to sit down and evaluate a couple other things. You have to evaluate the relationship. (48:51): You have to evaluate the work that's been done. And if you're working with subs, if you're working with other vendors, that can be a problem depending on the scope of what's owed. So you need to look at all those things and evaluate, is my time going after them in small claims court worth? The time I'm going to lose is recouping that money worth spending hours, days, weeks, going back and forth to court, managing documents, pushing them out, legal fees? Is that worth it? And sometimes it is and sometimes it's not. And one of the hardest things is to walk away from a situation where you know that you should be getting paid and you're not, but you're like, you know what? Me spending the next 40 hours of my time to chase down this $10,000 invoice is not going to be worth it at the end of the day. (49:35): And I know I'm going to spend the next 40 days just angry, angry, and mad, and not sleeping well anyway. So sometimes you just have to say it's not worth it and walk away, and that's really hard to do. Make sure you write off that as bad debt on your taxes so that you're getting that off as a tax thing. But hopefully that relationship that whatever you've experienced and learned will help you in your next projects with future clients and being aware and setting expectations again, it hasn't happened very often does happen. Hopefully it's happening less and less as independent. Working becomes bigger, but that's the biggest thing. You just have to evaluate all those things and make a decision and then when you make that decision, don't look back. You're like, you know what? It's not worth my time. This is a bad situation. This is a client I'm not going to work with again. And I will tell my friends, I won't bash them. I'll tell my friends, be cautious working with this person and I'll move on. And I think it's a decision you have to make and like I said, not look back.", "token_estimate": 691, "speakers": ["Maari Casey"], "start_timestamp": "48:01", "end_timestamp": "48:01", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "535ff8f7-6f38-4408-a718-83cd60746d34", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 28, "content": "Cole Heilborn (50:33): How viable is small claims and if you do go that route, what do you need in order to make sure that that swings in your favor?\n\nMaari Casey (50:42): I haven't actually gone all the way through small claims just because I did that time evaluation. I was like, this is not going to be worth it. But really it's a lot of documents that you just need to get from. You can go onto your state site, pull 'em all down and print 'em all out. We have a couple of lawyers that can review it. I think it's nice to have, nice to have legal counsel just to look through things. Even if you can do it like a la carte, A couple lawyers, a couple lawyers I know will review things a la carte as opposed to hourly. So it's nice to find a resource, but I mean, I think as long as you can show it and be really clear, then usually it'ss a good resource depending on, again, that evaluation of like, is this time worth how much I would recoup and how much I would lose?\n\nCole Heilborn (51:27): Well, Mari, we've covered a variety of different topics today. Is there anything that we have not gone over that you think is super relevant or something else to be considered?", "token_estimate": 294, "speakers": ["Cole Heilborn", "Maari Casey"], "start_timestamp": "50:33", "end_timestamp": "51:27", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "c5dc7877-9eb1-44df-948e-6a669b9ac953", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 29, "content": "Maari Casey (51:38): I think we've covered all the clienty things. I mean honestly too, I think the big thing is these are the things that scare people a lot of times from working, and you don't need to know any of this to start. I think it's smart to read and pay attention, but you'll get it. Get better at these things incrementally as you work. I think the things with small claims court and that stuff is, again, it's all goes back to how you start the relationship. Managing expectations, putting together your documents clearly, and just being okay, communicating, over communicating. I think a lot of times too, we feel a little bit like an imposter syndrome. Like I'm not a real business, I'm just one person, and so we don't do all of those steps that a real business would do as far as contracts and legal and timelines and expectations. But it's important to really do it because if your goal is to continue to grow your business, these things need to be in place just to protect you. So putting those parameters and fences around stuff is super essential, but it shouldn't intimidate you to start doing that one piece at a time. I think the other piece is just remembering to mentally separate yourself from your business. I think that helps to take that emotion out of a lot of these more difficult things.\n\nCole Heilborn (52:49): Well said. If folks want to follow along with you personally, or if they want to learn more about UN company, where can people go to connect?\n\nMaari Casey (52:56): You can go to our website, which is we are un company.com. You can also follow us on LinkedIn and Instagram. We have several blogs, articles and resources, especially on our website. All of our resources are stored there, so there's toolkits. There's a lovely p and l sheet budget calculator, set your rate calculator, some tools and webinars on project management and conflict and stuff are all there, so I'd love for people to check it out.", "token_estimate": 488, "speakers": ["Maari Casey", "Cole Heilborn"], "start_timestamp": "51:38", "end_timestamp": "52:56", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "edf1bb53-64bf-4e34-ae82-ce047081a9ca", "episode_id": "262cf930-5708-4f6f-a00f-0cbe945f4676", "cms_item_id": "68225dfc7bb476527f8c4888", "chunk_index": 30, "content": "Cole Heilborn (53:19): Awesome. Well, Mari, thank you so much for your time. This was a lot of fun. I feel like we just covered all the things that are not exciting about freelance work, but are the things that have to be done in order for people to enjoy the exciting parts of their job.\n\nMaari Casey (53:34): Yeah, yeah, exactly. Those are all those things that you stress out about and they're manageable, so that way, you know, can move into building a business and not worry about those other things.\n\nCole Heilborn (53:44): Yeah, absolutely. Well, thank you again for your time folks. I've checked out some of the resources that a company has on their website and I would highly recommend go and checking out some of those things that Mari just mentioned. They're pretty slick and very helpful resources. Mari, if folks want to follow along with you, if they have any questions, can they reach out to you or is there a good channel where they can go to do that?\n\nMaari Casey (54:07): Yeah, we're on Instagram, also LinkedIn. You can follow us on LinkedIn. You can reach out to me on LinkedIn and then if you go to our website, there's a whole section for folks who are interested in possibly working with us as a freelancer. You can sign up there that drops you into all of our emails, and then it also connects you with the team here.\n\nCole Heilborn (54:25): Okay, wonderful. Well, Mari, have a great rest of your day and best of luck as you guys continue on the journey of with UN Company. I'm excited to see where you guys go and the types of resources and projects that you guys put out in the future.\n\nMaari Casey (54:40): Yeah, thanks. Thanks for having me.\n\nCole Heilborn (54:42): No problem.\n\nMaari Casey (54:42): See you. Bye.\n\nCole Heilborn (54:46): Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 494, "speakers": ["Cole Heilborn", "Maari Casey"], "start_timestamp": "53:19", "end_timestamp": "54:46", "podcast_index": 97, "episode_name": "Ep 97: Managing Clients as a Freelancer | Maari Casey | Uncompany", "slug": "ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "web_url": "https://www.portsidepro.com/podcast-feed/ep-97-managing-clients-as-a-freelancer-maari-casey-uncompany", "guest_name": "Maari Casey", "guest_title": "Founder & Owner of Uncompany", "categories": ["creative"], "short_description": "Freelancer month continues with a conversation about how to manage clients efficiently and effectively as a freelancer. In this episode, Cole sits down with Maari Casey.", "podcast_length": "55:05"}, {"id": "612dac0c-8c15-4c94-a53c-d4f973c099ba", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 0, "content": "John Entwistle (00:02): A lot of people get really hyper-focused on how do I get this stuff in front of people? And I think really it's just about consistency, right? The consistency is what is going to elevate your chances to get noticed or seen. And if you try and time things, you're probably going to send yourself insane trying to time something. So really just, I think just staying consistent with getting your name out there. As long as you're skilled at your craft, it will pay off eventually. I think it's just, yeah, really just keeping consistent with getting yourself out there.\n\nCole Heilborn (00:33): Welcome to the Back Country Marketing Podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam, or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Holborn, and today I'm sitting down with John ENT Whistle. He is one of the account directors and content strategist over at Origin. He's also a freelance photographer. John, how are you doing? I'm\n\nJohn Entwistle (01:19): Doing really well, Cole, how are you doing?\n\nCole Heilborn (01:20): Doing awesome. Yeah, having a good day so far, and I'm stoked to be sharing the mic with you today.\n\nJohn Entwistle (01:26): Yeah, for sure. I couldn't really think of anything better to do on a rainy Monday.", "token_estimate": 437, "speakers": ["John Entwistle", "Cole Heilborn"], "start_timestamp": "00:02", "end_timestamp": "01:26", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "ea70dc19-3615-4687-9d6b-d8e368f5ed41", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 1, "content": "Cole Heilborn (01:31): Yeah, I know. I think, well, we're not too far away from you guys up in the Whistler area, and yeah, it's been a little bit of a dodgy day, but that's okay. It's actually, it's making the dirt it real nice for mountain biking here soon. Exactly. Yeah. Well, if folks have been following along, they know that this episode is the last episode in our month of March, which means it's also the last episode in our freelance focused month of content for the show. So John, I am super excited to have you on the show for our last episode today. I think we've got a great conversation ahead of us, and I look forward to getting into the weeds here. We're going to be talking all about, as a freelancer, how to work with an agency, and John, you work in an agency and you are also a freelance photographer, so you've got a really unique perspective on this topic, and I'm excited to dig in. Before we do, I'd love if you could just give us a quick little intro, quick little background as to who you are and what you do with Origin.", "token_estimate": 262, "speakers": ["Cole Heilborn"], "start_timestamp": "01:31", "end_timestamp": "01:31", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "954493ed-9e70-472c-9d79-79b9c5e2362b", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 2, "content": "John Entwistle (02:29): Yeah, for sure. So yeah, thanks for that intro. That was honestly pretty good. So yeah, well, my name is John Ell and I'm a content strategist primarily, and my kind of title also falls under account director here at Origin. And yeah, I'm always, whenever I meet people, and I think when we met on our intro call, people are always referring to me as kind of this weird person who they can't quite peg down what I am. And so, yeah, I think just generally in terms of my background started out way back when, just after I was born as a skier, have always been really, really involved in the outdoor industry. And I think that's the one common thread that as people do get to know me, that they'll find throughout my life is that the outdoor industry has always been near and dear to my heart. (03:18): But yeah, grew up competitively ski racing, ended up hanging up the boots for that to go to university. Ended up going to the University of Calgary, getting a degree in marketing and tourism management or Bachelor of Commerce in marketing and tourism management from there, which if anybody has been to Calgary, it's a prairie town just on the edge of the Rocky Mountains. But I was fortunate enough to continue to be able to coach skiing through my time while I was out at school there. And yeah, I think as I kind of neared completion or neared graduation, I was given the opportunity to join the co-op program at the University of Calgary and ended up landing myself in, I dunno what I still consider to this day, to be one of the coolest co-op placements probably in existence, which was at CMH Heli skiing out in Banff. (04:03): So yeah, I got the opportunity, honestly, I don't know if there's anybody else who has done a co-op where they've been heli skiing within three weeks of their first co-op experience, which for me was just a complete dream come true. I remember just being completely over the moon, and honestly, still to this day I look back at that experience and just kind of wonder how the heck I ended up in that position. But yeah, I was really fortunate to work with a team of really accomplished and experienced marketers at that point in time. It was definitely one of the first experiences that I had with the culmination of storytelling versus marketing and how those two things came together, got the chance to move to Banff as well. And while living in Banff, I picked up camera for the first time. That's kind of honestly how I started into this whole journey in photography as well. (04:59): I still maintain that living in Banff, it was pretty much impossible to take a bad picture. I started taking pictures just out the back door and of things that I was seeing every day. And it was also kind of at the rise of social media, so started posting things on social media and just started getting a lot of positive feedback, which now is just a totally different world than it used to be then. And yeah, I think just really just started taking photography a little bit more seriously. But yeah, I've always really kind of from a career perspective, focused more on that marketing side of things, marketing strategy. So after my co-op, I did actually end up staying on at CMH for another four years, four and a half years. Worked as a marketing specialist there, managed film shoots, got really heavily involved with our CRM and marketing or email automation side of things, and ended up leaving there for, I dunno, bigger promises in tech I guess, which was actually pretty short-lived. (06:04): I did live in the tech world. I consulted at an agency out of Vancouver for a couple of years, and I think there was a part of me that was just missing the outdoor industry, so bounced around a little bit, kind of in the middle there and found myself at Origin about six years ago now. So yeah, I've been working at Origin about five and a half, six years now. Started off here actually as our marketing manager, so doing internal marketing for Origin and then have kind of transitioned, well, transitioned first onto the account side of things and then now work as an account director and content strategist. So it's been really interesting for me looking back on the fact that I picked that camera up way back when in Banff. And now that I work at Origin, I mean, I work with some of what I consider to be some of the most exciting outdoor clients in the world, and there's just been some really cool opportunities to flex those photography muscles on the side as I'm kind of developing a lot of the content strategy. So yeah, that's pretty much where I find myself today, and I'm honestly pretty excited for what the future holds too.", "token_estimate": 1172, "speakers": ["John Entwistle"], "start_timestamp": "02:29", "end_timestamp": "02:29", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "43351192-cc1d-458d-a0de-3c1045e0b2e6", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 3, "content": "Cole Heilborn (07:18): Yeah, awesome. So a lot of the feedback that we've received from folks from freelancers is how do I get work? How do I work with brands? How do I work with an agency? And agencies, at least maybe from the outside look like they're this giant conglomerates, they don't really have a person or a face necessarily. And I think some photographers look at agencies as this gold mine of potential work and you're like, oh, if only I could just talk to someone, or if only I could just get my portfolio in the door, that would be such a great opportunity. And so I guess I'm curious from this idea, what have you observed? What is the challenge that a lot of freelance photographers or just freelancers in general face trying to get in front of an agency and at least have the opportunity to be considered?", "token_estimate": 206, "speakers": ["Cole Heilborn"], "start_timestamp": "07:18", "end_timestamp": "07:18", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "b7db2b52-bb7e-4bf7-b949-84a53f74032f", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 4, "content": "John Entwistle (08:12): Well, and I think that's honestly the key part is the consideration side of things. So it is one thing I would say a lot of people are really focused on the awareness side of things and just how do I get seen by agencies? How do I get recognized by agencies? And honestly, I would imagine the same thing happens on the brand side of things quite a bit as well. And honestly for me as a freelance photographer, I am kind of in that boat sometimes I work on the inside of an agency, but I'm also just like, how do I get in front of the right people? And I think for me, well, not just for me, but for us at Origin, because we are such a niche agency in the outdoor industry, there is a lot of, I will get a lot of questions and a lot of my photography peers honestly pick my brain all the time because I do have that inside lane into an agency. (09:00): And a lot of the time I get that question, how do I get on your list? How do I get on your consideration list? How will you guys consider me for jobs? And the reality is, I would say 90% of the time that I get a request like that from somebody who's already on my radar, they already exist out there. They're relatively well known, or they're up and coming within the outdoor industry and they are known. So I do think that a lot of those traditional channels in terms of how are you going to get seen by the right people, LinkedIn is obviously huge. Instagram, having blogs, websites, I am occasionally, especially from a photography perspective, quite blown away at the number of photographers that don't have websites or don't have up-to-date websites. But I think just if you have those channels and you're involved in an industry, I would say there's very few times where we actually get reached out to by somebody and we haven't heard of 'em, especially, I mean, origin is quite core to the ski industry and the travel and tourism industry. (10:01): So within those industries it is quite rare. Recently we have expanded a little bit. We've done quite a bit of run work. Lululemon's one of our clients and we've done some run work with them. You can see the poster behind my head, but, and the run world is one of those things where we did have a couple of people reach out to us and run just wasn't one of those areas that we had a ton of people within our Rolodexes, if you will, that we're within that wheelhouse. So yeah, I think just understanding that niche of the agency really probably does mean that you are probably on the radar there.", "token_estimate": 632, "speakers": ["John Entwistle"], "start_timestamp": "08:12", "end_timestamp": "08:12", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "49168a25-c715-4511-88c8-29df9a6642ea", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 5, "content": "Cole Heilborn (10:42): Yeah, interesting. Let's back up a little bit. I guess, what does an agency or Origins process look like? When would you consider working with a freelancer?\n\nJohn Entwistle (10:51): For sure. Yeah, so I think from when do we work with freelancers perspective, there's really two. And honestly, we work with a ton of freelancers at Origin. So there really are two kind main areas where we would tend to work with freelancers. One is definitely more on the specialized skill side of things. So if there is a specific project or a concept that we come up with that we're looking to execute on, and we just don't have the internal expertise to do that. One of the main examples that comes up quite frequently right now is FPV drones. We are constantly looking for FPV drone operators and skilled FPV camera operators because it is something that is just kind of a hot button topic these days when it comes to marketing. And so yeah, that would definitely be one area is when we have to go outside of just our core service offering and really find a contractor or a freelancer that can fill that gap. (11:53): And then the second piece would be just more of a capacity issue, or not even an issue, but just a capacity opportunity where maybe all of our writers are currently tapped or we have all of our writers assigned to something else, and we will be looking for just really more capacity in one of our core skills. I will say that in that second instance, we do tend to have a pretty trusted pool of freelancers that we will go back to over and over, and we've developed relationships with those people or people over the years. I think even if you go to our website, you'll see that we're always on the search for what we call perm lancers, and they're just, honestly, sometimes they feel like fixtures of the origin family, but they're not on our payroll, they're not salaried employees, and they're much more on that kind of contract to contract basis.", "token_estimate": 495, "speakers": ["Cole Heilborn", "John Entwistle"], "start_timestamp": "10:42", "end_timestamp": "10:51", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "d41b8e7b-a811-401c-b359-e49d6c00c881", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 6, "content": "Cole Heilborn (12:44): Sure. Interesting. And so from, I guess a process scenario, as you guys are working with the client, where in your process are you generally connecting with freelancers? Are you connecting with freelancers in the sales cycle? Are you connecting with them after you already have a brief and a treatment where in that process?\n\nJohn Entwistle (13:06): Yeah, that question is such an interesting one because it honestly depends so much on what the project is and who the client is. But a quick answer would just be in every single one of those instances we have and have not worked with freelancers. But yeah, it is definitely something where, and I would say more on that specialized freelancer side of things, that would be where we would tend to partner with a freelancer more on the concepting side of things, especially when it gets into really specialized things. Again, I'll use the FPV drone thing because it's just something tangible that we can all wrap our heads around right now. But that would be something that as we were concepting something, we would want to make sure that we weren't concepting something that was impossible or something that was illegal or having that expertise in the room brainstorming might be super valuable. (13:58): And then I would say though, the majority of the contracting that we do is more on the execution side of things. So the internal ideation, the concepting, all of that tends to happen with our internal origin team and we really do look more so to those freelancers or contractors on the execution side of things. So we have a bit of a defined direction. It honestly just, it's definitely a bit of a safer approach for us, I would say, because it does allow us to set up what those guardrails are going to be ahead of really diving into it with a freelancer. But yeah, it's definitely, I would say it can play in any of those areas, but it would definitely skew more to the execution side of things.\n\nCole Heilborn (14:40): Gotcha. If you had to guess, what are some of the biggest misconceptions that freelancers assume when trying to work with an agency?", "token_estimate": 533, "speakers": ["Cole Heilborn", "John Entwistle"], "start_timestamp": "12:44", "end_timestamp": "14:40", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "5696c169-a25b-43b2-bf05-98bc84f875a8", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 7, "content": "John Entwistle (14:49): I would say the biggest thing is that big, scary, unattainable, unachievable, unapproachable, just clubs almost. It is something that I get a lot of, and honestly we see it with a lot of freelancers too, of just this starstruck like, oh my God, I'm finally talking to an agency once we actually do start that engagement. So yeah, I think, and this is really easy for me to say in my position, but we are constantly looking for different ideas, different perspectives. We really respect a lot of the creativity that exists out there. That's really our MO is to be as creative as possible within the outdoor space. So I think as much as the work that we end up putting out, the back end is very polished and is some of the highest quality stuff out there, and that doesn't just go forward and that goes for all agencies, right? Agency, that is what you do. You put out the most polished and creative work out there. I think it can often seem intimidating to freelancers of just like, how am I going to contribute to that? Or it might be that we're working with production budgets that a freelancer hasn't seen before or just all of those things I think all really culminate into us probably seeming much bigger and less approachable than we truly are.\n\nCole Heilborn (16:19): Sure. So it sounds like there's two phases, the awareness phase and the considered phase. I'm curious if we can break those down now knowing a little bit more about how you guys operate with freelancers. So the awareness stage is well-defined that for us, what is that?", "token_estimate": 392, "speakers": ["John Entwistle", "Cole Heilborn"], "start_timestamp": "14:49", "end_timestamp": "16:19", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "c880edad-9161-4191-b093-458e7bfd4d9a", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 8, "content": "John Entwistle (16:35): Yeah, so I think from an awareness perspective, I mean our work is generally I would say quite predictable. We know what kind of work we're going to be doing. We don't know what the final product is going to be, but we know who our client roster is, we know what is happening in the industry, we know what's happening in the market. And so I think from an awareness perspective, and there are a lot of people at Origin that are just constantly paying attention to what is going on out there in the industry, I can't tell you how many photographers I follow on Instagram. Our creative directors will follow designers, writers, just interesting creative people. And honestly, a lot of the times the people that we will hire as freelancers are people that we look to for inspiration. What is this person doing or what's happening here? (17:29): It's not always just competition and brands that we're looking to for inspiration. A lot of the time it is kind of that freelance side of things and just those kind of voices of reason or voices of influence, I should say out there in the outdoor industry, actually, sorry, not just the outdoor industry, we often look outside of the outdoor industry because we don't want it to just be this bubble that we operate within. So I think one of our designers actually two weeks ago went down to Vancouver and he rode his bike around the city and just took pictures of murals and was just trying to gain some perspective of, okay, what else is going on in the art and creativity perspective? And that might even seem slightly irrelevant to this conversation, but honestly if we had a, and we have done this before, we designed the North Face Store in Whistler for instance, and we actually hired a mural artist. So I do think that the more out there you can be and just being that voice of influence within that industry, we're paying attention. Our job is to stay on the pulse of that.\n\nCole Heilborn (18:40): And I guess what makes a freelancer on your radar? What makes them become aware or you guys aware of them?", "token_estimate": 520, "speakers": ["John Entwistle", "Cole Heilborn"], "start_timestamp": "16:35", "end_timestamp": "18:40", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "2e8cac5b-0f9b-499e-8596-54c477c4d755", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 9, "content": "John Entwistle (18:51): Yeah, it's a really good question. I would say a lot of it does have to do just with references. We will get either referrals or references or see somebody's work that gets published somewhere. That's definitely a big part of it is who's getting published in magazines, who is participating in conferences or art shows, even local art shows. So I would just say getting work out there. The other side of that, and we do get a lot of just kind of cold calls, like a random email, here's my portfolio, please let me know if there's any work for me. And I would say those emails definitely do not get ignored as much as sometimes it may feel like it gets ignored. (19:43): I probably get, I dunno, maybe 10 of those emails every couple months. So it's not like we're getting a ton of them, but I would say that there's a very, very slim chance that you would email us with a portfolio and we would email you back immediately and say, great, we have this project for you. Those things very rarely happen. So it definitely is a little bit more of a slow cooker type approach. You probably reach out to us here, we see your name somewhere else, and it is definitely, there's very rarely just that one shot wonder that leads to a solid engagement. It much more is that building up over time. And that's definitely something that when we're looking at sourcing freelancers, we want people with track records that actually are able to produce time after time after time. We don't want to just go hire somebody because they did one great thing one time. So yeah, I think just that kind of constant drip approach is definitely pretty interesting.\n\nCole Heilborn (20:42): Gotcha. So it sounds like the portfolio obviously plays a huge role in just that awareness phase, moving from Aware to considered, and now hopefully they have a job. Where is that line in the sand? When do you cross from Aware to considered?", "token_estimate": 482, "speakers": ["John Entwistle", "Cole Heilborn"], "start_timestamp": "18:51", "end_timestamp": "20:42", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "aeabca52-a270-40ae-88c9-86d9b195a7ad", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 10, "content": "John Entwistle (20:58): Yeah. Well, I mean the consideration is really triggered when we get the job as the agency. So we're kind of aware of all these people and then when we have a job and we have a need, that's kind of what actually triggers us to start looking at, okay, who do we need on this job? What are we going to do? And so some of that, well, sorry, there's actually a couple of things that kind of contribute in there. I would say honestly the largest influence in that is just clients Do the clients have somebody that they have worked with in the past that they are comfortable with and that we want to work with. That is generally the path of, I don't want to say the path of least resistance because it honestly often just leads us to the best relationships and leads us to the best work. (21:45): But for us, it is truly the path of least resistance. We have somebody that we know the client is going to be comfortable with, it honestly shares a little bit of the responsibility of just sourcing that person if the client is vouching for them, then on our side, that definitely just gives us that little bit of extra comfort. But yeah, I would say for sure the client recommendations are kind of the leading factor there, but then I think it would really just outside of that come down to a bit of what I was talking about before, just really with that skillset. What are those skill sets and do you bring a specific skillset that really kind of fits what we're looking to do with this project? One of my favorite recent examples is we were just doing a video concept for one of our clients in the ski industry and digging through and part of the deliverables were also just photo selects. (22:44): And so we needed a photographer on scene or on set, and I just happened to be on my Instagram feed one day and came across this picture from a local photographer who I knew quite well, and he just posted this picture that was a hundred percent in line with the brand guidelines of this client that we were just in that process of coming up with this concept for, it was just like, oh man, this is a perfect fit. The client had mentioned this person, they don't know the person. We happen to know the person from a couple of other engagements out there. (23:18): Yeah, I dunno, one of my favorite sayings is Luck is when preparation meets opportunity. And I think this was just one of those perfect examples where this person has a really well established Instagram feed. Honestly, not all of their posts are in line with those brand guidelines, but it just came down to, it happened to be the right day. It happened to come up on my algorithm and we happened to be looking for photography services at that point. Yeah, and I think a lot of people get really bent out of shape, or maybe not even bent out of shape, but just really hyper-focused on how do I get this stuff in front of people? And I think really it's just about consistency. The consistency is what is going to elevate your chances to get noticed or seen. And if you try and time things, you're probably going to send yourself insane trying to time something. So really just I think just staying consistent with getting your name out there. As long as you're skilled at your craft, it will pay off eventually. And I think it's just really just keeping consistent with getting yourself out there. For sure.", "token_estimate": 847, "speakers": ["John Entwistle"], "start_timestamp": "20:58", "end_timestamp": "20:58", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "1480c85b-b4bf-4e77-814a-4ee1d8d5fbf4", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 11, "content": "Cole Heilborn (24:26): Yeah. So thinking about that example you just shared, that kind of seems like, well, frankly, a lot of luck coming together, as you said, the right time, the right place, the right photo that photographer posted. You were talking about consistency as a factor that you can control as a freelancer in terms of how frequently your name is hopefully getting out there outside of relying on the Instagram algorithm to feed content in front of agency folks, what are other ways that people can control that have some control over that scenario that are good practices?", "token_estimate": 147, "speakers": ["Cole Heilborn"], "start_timestamp": "24:26", "end_timestamp": "24:26", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "65623595-1614-4290-9eca-79584919cddf", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 12, "content": "John Entwistle (25:01): For sure. So I do think, and again, going back to the agency seeming like this big scary place, we really aren't, and we love beer. We love coffee at agencies, honestly, developing relationships with people within agencies and just a lot of those things are two-way streets. It's like I talked about how we're constantly looking at these feeds and looking at what exists out there and what innovation is happening. And a lot of times, honestly, just sitting down for a coffee with somebody, it can be a great two-way street. So I have a bunch of different peers, and for me, it's interesting because I do play on both sides of that fence. And I think a lot of my photography peers look at me and will call me and ask to go for a beer and just talk about what's going on in the agency world. (25:53): And then I conversely talk to them about what's going on in the photography world. Then we develop just really good two-way relationships. And again, I think that is, so you're never going to get a job from just one of those coffees unless the coffee just happens to be an interview and you aren't aware of it. But it is just that consistency and consistently having those conversations is really what just starts to develop those relationships. You start to become that voice of reason. And so I think definitely from a freelancer perspective, just identifying who the right people to be having those conversations with are, right? If you are a designer or a writer and you're able to have coffee with a creative director and an associate creative director, but it doesn't always have to be at the top levels of an agency either. Oftentimes, if you're a writer and you have a friend who's a writer within an agency and you're just having a conversation about what's going on in an industry, I've seen it before where some of our junior writers have come into brainstorms and said, oh, well my friend was telling me about this recent piece that came out in blah, blah, blah. (27:03): And they bring that to the table and all of a sudden it gets people thinking like, oh, well, who's this friend that recommended this thing? And what skill sets do they have? And would they actually just be the right person for this project? So I do think as much as agencies might seem like these big and scary things, even the hierarchies within agencies, I don't even want to know how many emails some of our creative directors get every day of just, here's my portfolio, check this out. So not being afraid to make those relationships at varying levels within the agency, because that can definitely bring a lot of value that you might not necessarily expect.", "token_estimate": 668, "speakers": ["John Entwistle"], "start_timestamp": "25:01", "end_timestamp": "25:01", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "c71ad3ba-f0ed-4c77-b0f1-d66f30eb66a0", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 13, "content": "Cole Heilborn (27:41): Aside from creative directors, are there other roles within an agency that are kind of those key holders towards those relationships with freelancers that people should be considering?\n\nJohn Entwistle (27:52): Yeah, I mean I think the creative director is definitely the final decision maker, so that is for sure the ticket. But yeah, like I said, I think really any of those kind of specialist positions where you can be having just those inspirational industry type conversations can be super effective. And then more so if you look at more my realm on the strategy and the account side of things, those conversations and those relationships can for sure be valuable. I would say they're not quite as valuable as they are on the creative side because what we'll end up doing is just making those relationships with people on the creative side. So ultimately the creative side is where you will need to be. But I would say honestly, any kind of door you can get, any kind of relationship you can make can be super valuable. (28:43): And then the one side of things that does exist in agencies is really more the resourcing. And we have people within our agency and our resource directors, our resource managers, and their sole job is to figure out who to put on projects. And they ultimately are the people who are responsible for those contracts, but they don't have a lot of say or weigh in terms of the skill sets that are required in those. So that would be maybe one trap that I would watch out for is just often if you're on LinkedIn and you see resource manager, resource director, you might think, oh, if I can get in front of that person, then maybe somehow I can get put onto a project and they can again route those to the right conversations. But they're definitely not the ones who, and they get inundated with things, with portfolios and with requests and all of that. So yeah, definitely keeping it much more on the what is your path to talking with somebody on the creative team. And yeah, that's for sure where I think the most kind of fruitful relationships can exist.", "token_estimate": 528, "speakers": ["Cole Heilborn", "John Entwistle"], "start_timestamp": "27:41", "end_timestamp": "27:52", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "ffe73909-68e3-4636-a78a-8aa226253cda", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 14, "content": "Cole Heilborn (29:49): Gotcha. Well, I'm sure many folks can relate to receiving LinkedIn spam messages or spam emails. Obviously if you're not on an agency's radar at some point you have to, well, many people reach out to an agency and say, Hey, here's my portfolio as you just described. What are good ways to do that and what are bad ways to do that?\n\nJohn Entwistle (30:14): Yeah, for sure. I think when you look at if you're a hundred percent right, there is a lot, we just get a lot of volume of requests for these things. And I think really understanding just generally how an agency works and I think specifically to origin, that's how I'll talk because that's kind of where I'm at right now. Not all agencies work exactly the same, but I think generally looking at the outreach to an agency as more of an inquisitive exercise as opposed to an expert or a, I dunno, you could call it bullish, kind of like, I'm going to come in here and I'm going to make an impact. It's such a fine line when you look at freelancers, and this is something that I often struggle with on the photography side of things, is just looking at, okay, if I want to work for me, I tend to work more with brands than I do with agencies. (31:15): I generally only work with Origin. But yeah, I think when you do look at it, it's like, okay, well how much of this approach should I take in terms of trying to figure out what is actually going to be required here as opposed to I know the answers or I have this solution. Because so much of the value that agencies bring is really around the collaboration and just the vetting of ideas, the development of ideas, and it really is a team effort in terms of getting to the final solution. And so a lot of the time we will, or not a lot of the time, but we quite often will have just people who reach out to us with a, I have this solution, I know you work with brand X and this is how you should do this, or this is how I would do this. (32:04): And I would say, it's so rare that you get that right, and it's not because it's not possible to get it right, but it's just because our process is so much more iterative and so much more we want input from a whole bunch of different people on the team to really get to that well-balanced approach. And going back to what we were talking about earlier, that's ultimately how agencies land on these really polished high quality creative pieces is because it has been vetted from a bunch of different angles. We've had copywriters look at it, we've had strategists at it, we've had account people look at it, we've had creative directors look at it, and it really is kind of the input of that broader team that really gets us to that final product. And so I think when we're looking at freelance kind of relationships and when we look at how we want those people to be involved, especially when it's not just on the execution side of things, but when it is in more of that actual creative contribution perspective, we really want to make sure that people are actually going to be valuable and effective players in that space. (33:13): So we do want them to bring their expertise, but we don't necessarily look for people who are just saying, this is exactly what we should do. You might get that right 1% of the time, and honestly congratulations if you do, but realistically, it's just probably going to fall pretty flat because yeah, it's not like we're looking for the right answers. We're looking to collaborate with people on getting to the right answers.", "token_estimate": 883, "speakers": ["Cole Heilborn", "John Entwistle"], "start_timestamp": "29:49", "end_timestamp": "30:14", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "acbb9233-85e6-4389-89a1-462fffd11274", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 15, "content": "Cole Heilborn (33:39): Okay, that makes sense. Is there a recent example that you could pull from where you got an email or an inquiry from someone and it was very well thought through, very well put together and it cut through some of the volume of emails you had received that week?\n\nJohn Entwistle (33:59): For sure. I think the best examples that we get really are purpose built portfolio examples. So whether it be a really well curated example or a really well curated set of previous portfolio examples, I'm working right now in really specifically in the social content space. And so we actually just had, and we've just gone through kind of an interview process where we're not sure if we're going to hire a contractor or if we're going to hire a freelancer, or sorry a freelancer or if we're going to hire a full-time employee. But some of the strongest elements that really came forward were these kind of curated profiles of, okay, here's what I've done for previous clients or yeah, it generally is work of here's what I've done for previous clients and here's how I've kind of curated this in a, okay, I did this work for Apple, let's say because it's the most famous brand in the world, and I created this TikTok for them. (35:07): I created these Instagram stories, I created this long form YouTube video or was involved in the creation of these things. And really kind of showing the thought process behind that because I think that's so much what we evaluate for is the thought process and how you're able to think as opposed to the execution of it. And conversely to that, I've seen bad examples where somebody will say, I took your client and I created this suite of social ads for them. And a lot of the time we can start to see the thought process there. But again, it's really that thought process that we're trying to evaluate as opposed to the end result. Because like I said, it is such a team effort to really get to that end result. And then I think too, just looking at the broader portfolio, once you get into specific skills like photography or writing or design, obviously we will want to make sure that this person is competent within those spaces. But again, I think it does go back to that really just showing us that you have the capacity to think within just a process that we'll actually work for or have a thought process that will work with our team as opposed to really just coming straight out of the gun or straight out of the barrel with here's exactly what I think you need.", "token_estimate": 630, "speakers": ["Cole Heilborn", "John Entwistle"], "start_timestamp": "33:39", "end_timestamp": "33:59", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "7d3413b3-324e-46dd-bbd2-f7827a77d89a", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 16, "content": "Cole Heilborn (36:30): Interesting.\n\nJohn Entwistle (36:31): And I will preface that by saying I definitely operate more on the photography side of things and on the account strategy side of things, I know that our creative directors, for instance, when they're evaluating freelancers on the writing and the design side of things, it is a little bit more technical, definitely wanted to make sure that those design skills are up to industry standards and all of that. But I think even there is still quite an emphasis on just the kind of thought process that goes into a lot of your work.\n\nCole Heilborn (37:04): Gotcha. So let's assume that you've sent off, I'm a freelancer, I've sent off an amazing email that completely explains my process around my body of work and you're very interested and now it's just a matter of staying top of mind. And as we were talking about earlier, that drip process, what's an appropriate cadence for maintaining contact? Should I email you every week? Should I be messaging you on LinkedIn every month? How do I stay in contact with you?\n\nJohn Entwistle (37:37): Yeah, for sure. So I think in terms of staying in contact with us, I mean\n\nCole Heilborn (37:44): Would is that good or bad?", "token_estimate": 306, "speakers": ["Cole Heilborn", "John Entwistle"], "start_timestamp": "36:30", "end_timestamp": "37:44", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "e40d31a5-eeb9-4559-8ea8-94c6499193d7", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 17, "content": "John Entwistle (37:46): It is good. I would definitely say staying in touch is good. And I would say that doing it with purpose, if you have something, the best emails I like receiving are, Hey, I just did this. I just got back from this shoot and it went really well and this is what we were able to do. And much more of those anecdotal kind of just keeping you top of mind, the constant. Do you have any work for me? Do you have any work for me? Do you have any work for me? Honestly, I get frustrated also trying to find work for the agency. So it's like if I have work then I'll let you know. And also if I could hire every talented person that I had in my Rolodex, I totally would. I think it really is from our perspective and just from what we're looking at, really try trying to find the right fits for the right things. (38:39): And so I think just trying the right fits for the right projects. And so as a freelancer, if you are trying to just stay top of mind, honestly, finding or sending those things over to us that we will potentially use as inspiration are the things that will make us go, aha, this person sent this piece of inspiration and we're working on this project and this is what we should do. And then there will be the occasional time where we have a project that all of a sudden lands and we're scrambling to get the right people on it. And if you're top of mind, then that's going to be kind of who we're going to. So yeah, I would say definitely focusing on that, kind of reaching out with purpose, not just reaching out with requests or reaching out with any kind of specific, I dunno asks or anything, but more reaching out with relevant pieces. I have seen that overcooked as well. I've definitely seen people who have replied to case studies that we've put out or whatever, and they send us a 16 page essay on what they thought about our case study. Sure, I appreciate it, but it just, it's just not a valuable use of anybody's time. So yeah, I think again, it is about that balance, but reaching out with purpose is for sure a good thing.", "token_estimate": 519, "speakers": ["John Entwistle"], "start_timestamp": "37:46", "end_timestamp": "37:46", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "936de80f-6b27-4ff5-bbdc-6b8c60b37a17", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 18, "content": "Cole Heilborn (40:00): And I guess just to reinforce, timing seems like a very important component of all this. Maybe there's a freelancer whose work you love and it seems like a great fit, but in three months later, maybe there's a new project that would fit that freelancer's portfolio very well, but the freelancer and the agency have lost touch, and I'm assuming that unless if the freelancer made that much of an impact to the agency, chances are they're not going to dig back and find that portfolio of that one person and then reach back out to them, or", "token_estimate": 140, "speakers": ["Cole Heilborn"], "start_timestamp": "40:00", "end_timestamp": "40:00", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "f1e1444f-ec77-4d47-881d-8881ef2367de", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 19, "content": "John Entwistle (40:32): Yeah, there is definitely a pretty big effort on our side to find the right person for the right thing. So I would say if you made a big enough impact, and I don't think that that impact needs to be maybe as big as you're alluding to. I think, yeah, we do kind of have just those active rosters of people that we have in mind for things. The thing too is, and definitely in the outdoor industry, the outdoor industry is so cyclical, it's so seasonal. For all of our ski resort clients, we know that they're all going to be selling seasons passes sometime between, well, I don't know if you're the epic pass you launch today, but most other ski resorts are selling their ski seasons passes sometime between July and October. You're selling ski vacations sometime between September and November, and that's when a lot of these marketing pieces are required. (41:26): So I do think there is just an element of being tuned into that industry that can definitely help the timing aspect of that. But for us, if I remember something great from October last year, I will most likely remember it. But that is definitely where having those consistent coffees with somebody, if I saw something in January of this past year and that was the only thing I saw of it, I might've forgotten it. But if I've gone for coffee with that person four times over the last two years and I saw something great that they did in January, chances are they're probably going to be pretty top of mind. So yeah, again, I think it's just that balance of finding the right timing, understanding when some of these things might actually start to come up. If you're pitching us on doing a ski campaign photo shoot in April, chances are we're probably not thinking about that. But as the fall starts materializing and snow starts to fly again, then that's probably a little bit more when we're actually starting to look to resource some of those things.", "token_estimate": 485, "speakers": ["John Entwistle"], "start_timestamp": "40:32", "end_timestamp": "40:32", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "f0b8dd48-3674-4f91-b311-51e4916f7aa2", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 20, "content": "Cole Heilborn (42:30): Gotcha. Interesting. You've talked about some of the things that folks should avoid doing, one being very bullish and just kind of barging in the door and saying, I have the solution. And then obviously I think people could come up with some others on their own. What are some other practices that are good practices that aren't very common or are not considered\n\nJohn Entwistle (42:52): Well, actually maybe in terms of things that are maybe a little bit more old school, definitely the whole idea of a physical portfolio is something that I know that there was a big focus on probably honestly only 10 years ago. And occasionally we will still get a letter in the mail of printed images. And I'm honestly a bit on the fence of that because I do get the allure and the excitement of having something tangible in your hands. But at the same time, when you look at the actual payback or ROI on actually getting some of those things out there, I think there's just definitely a major decline in terms of what that ROI is right now. And so I think just definitely looking at having that strong web presence, having strong social media channels, like I said off the top, I'm blown away sometimes by the lack of just online portfolios that a lot of people have. (43:54): And yeah, I think just the value of really being able to express yourself online in an effective way is just such a valuable skill that I think is not lost on a lot of people, but it's definitely lost from time to time. And I think too, looking at the nature of the work, so much of the work that we do now is digital. So if you're able to actually express the work that you do appropriately through digital mediums, then we're able to actually look at that explicitly against how we would express that work digitally through a client's lens. So yeah, I think just really that kind of honing in on that digital portfolio as opposed to some of the more traditional print elements or in-person, like the art of an email versus the art of the phone call. As sad as that might be, it is just kind of the way that times are going for sure.", "token_estimate": 531, "speakers": ["Cole Heilborn", "John Entwistle"], "start_timestamp": "42:30", "end_timestamp": "42:52", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "6db188fd-b914-438d-a99d-2dfae3b667e7", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 21, "content": "Cole Heilborn (44:58): I guess we talked about the idea, but cold calling, cold emailing, are those good? Are those bad?\n\nJohn Entwistle (45:06): I would say that a cold, well, these days, again, phone calls are just so strange. And if somebody calls me, honestly, I'm at a bit of a loss as to what to do with it. I can't say that it would necessarily make me look negatively at anything, but I do think just understanding, again, the pace and the tempo of an agency, I would for sure recommend the cold email over anything. And honestly, cold emails are not a bad thing. I would say we definitely get a lot of them as an overall agency. I would say there's massive inconsistencies in terms of who those get addressed to or where they get routed through the agency, but we're pretty good at distributing those internally. And occasionally you'll just get an email that's forwarded from somebody else in the agency that says, Hey, so-and-so reached out. Just take a look through their stuff and feel free to add them to your list if you have it or if you have interest in what they're putting together. (46:08): And so I would say unless you're completely off the mark or you're going in with that really bullish approach like we were talking about earlier, then a cold email can definitely be a good thing. And again, I would make sure that that gets followed up with, can we go for coffee? Should we meet up for a beer? Here are my social channels, here's my email newsletter. What are those kind of areas that you can really open up the doors for those ongoing relationships? Because definitely just a, here's a cold email and I'm expecting work out of it and I'm never going to talk to you again. Those work 0% of the time. So really using that to kind of open up that relationship and that conversation can be valuable for sure.\n\nCole Heilborn (46:54): Gotcha. Interesting. Well, I feel like we've covered a variety of different topics and ideas here. Is there anything that we're missing that you think is important to consider?", "token_estimate": 509, "speakers": ["Cole Heilborn", "John Entwistle"], "start_timestamp": "44:58", "end_timestamp": "46:54", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "bd7d9cd3-591e-4b91-b88f-d081f81918ca", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 22, "content": "John Entwistle (47:05): I think the biggest thing, and we have talked about it, but if I had to summarize everything, is that agencies are really in the business of creating cool, creative, innovative things. And we're always really interested in talking to anybody in that space. So it uplifts our industry. It makes everything better when we all kind of collaborate those things. So yeah, I would just say don't look at agencies and to that matter, brands maybe a little bit less, but there definitely are brands out there that are seeking that same thing. So yeah, I would say that's really the biggest piece is just getting that collaboration going, getting excited about creative or even strategy or whatever you want to get excited about what's happening in the industry, but the more that we can all get excited about that, the more great work we can ultimately produce.\n\nCole Heilborn (48:01): As a photographer yourself, having, I know you do photo work with Origin, but having kind of the inside track or insider's knowledge around how agencies work, does it make it easier or more difficult for you to go after your own freelance projects with brands or with other agencies?", "token_estimate": 297, "speakers": ["John Entwistle", "Cole Heilborn"], "start_timestamp": "47:05", "end_timestamp": "48:01", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "f58f2ebd-9935-493b-bf48-c3256d83d900", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 23, "content": "John Entwistle (48:19): Yeah, it's hilarious actually. I'm probably going to listen to this podcast after the fact and take a whole bunch of my own advice because it's definitely one of those things where it's easy to say all these things, and honestly, when it comes down to executing it, it's so damn hard. So yeah, I think for me it really is. I definitely focus a lot on the online presence, online portfolio, social media has been a huge tool for me that has worked really, really well. And so I don't necessarily see that going anywhere anytime soon. The nice thing for me, and I laugh because my online presence and I have built that up so much around my photography business, but realistically, when you look at it from my time perspective, my income perspective, 95% of my life is spent on the strategy side and the origin side. (49:14): And it might be like 5% that is focused on the photography side, but when you look at it from a online perspective or an online presence perspective, that's actually flipped. I'm like 95% out there and photographer guy. So I do have the luxury of being a little bit more selective in terms of what I do take on and what I don't take on. But then that also puts me in a really great position where all these connections that I do make, I'm able to kind of sift through. And when I do see a friend that puts something out on their Instagram that's aligned to brand standards, I can say, Hey, that actually is a great fit and let's go with that. So yeah, I totally understand the fact though that giving advice is a lot easier than actually actioning on it for sure.\n\nCole Heilborn (50:00): Is having an Instagram, is that a mandatory, let's say you've got a good website, do you have to have, at least for a visual artist, do you have to have an Instagram in order to be considered in all of this?", "token_estimate": 461, "speakers": ["John Entwistle", "Cole Heilborn"], "start_timestamp": "48:19", "end_timestamp": "50:00", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "d30c638a-9646-4ca9-833a-3420a3002c39", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 24, "content": "John Entwistle (50:16): I would say so, and I would say that that's still the case, because it definitely was the case five years ago, and I would say it's still the case today and whether or not it is in five years, I honestly don't know. So I do think that that is changing really quickly, but right now, so many people are still using Instagram, even just as a reference check. You have a portfolio, you have a website, okay, how are you actually showing yourself out there? And I think generally in the way that Instagram especially is moving, definitely the feed side of things tends to be a lot more curated. And that's one of the big transitions that I've seen for myself in photography recently, is I used to post to Instagram three times a day and I used to go out and shoot stuff specifically for Instagram, whereas recently I actually went back through and deleted, I dunno, 75% of my Instagram feed and really just left that as a curated overview of what I'm about and who I am. (51:26): And so it really does just kind of sit there as a portfolio piece or a portfolio example. And then I've actually found a lot of value in stories and in working with the brands that I work with is definitely something where it's just so easy to tag people in stories. You tag people in stories, they repost your stories, they're happy that you're sharing content. So a lot of the brands that I do work with, that's definitely like, it's who you keep in touch with or it's how you keep in touch with them. A lot of the time's just by tagging them in stories of either imagery and well very candid imagery. It can be me on the skin track or it can be me behind the scenes on a shoot, but yeah, you're tagging whatever company it is that you're working with, and I think a lot of that just kind of more organic and true to yourself, content that exists on Instagram is really interesting.\n\nCole Heilborn (52:24): Yeah, okay. Interesting.", "token_estimate": 484, "speakers": ["John Entwistle", "Cole Heilborn"], "start_timestamp": "50:16", "end_timestamp": "52:24", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "3a5fbf24-ff67-4aff-af3e-7ae387aac29d", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 25, "content": "John Entwistle (52:27): Yeah, and then, I dunno, I'm so intrigued by all of these emerging platforms and I mean, TikTok is arguably emerging, but one of the brands that I work with, RMUI make skis and all that good stuff. I know I was having a conversation with them the other day, and I have a TikTok that it definitely was a bit of a one hit wonder, but it has 1.5 million views, and I was just talking to the guys over there, I was like, Hey, I have this TikTok, it got 1.5 million views, I don't really, and you just see their eyes kind of go like, whoa, we don't know what that means either, but it sounds impressive. So I do think playing around with just those new and emerging channels can definitely be a super valuable thing as well. If you do unlock some kind of ticket there, then that can be super valuable and perceived really well in the eyes of brands.\n\nCole Heilborn (53:17): Yeah, interesting. Cool. Well, John, we're coming up on the end of our time for today. Is there anything else from your perspective that we should touch on?\n\nJohn Entwistle (53:27): I don't think so. I think that was a really good overview of just that relationship between freelancers and agencies for sure.\n\nCole Heilborn (53:35): Yeah, I think that was a lot of fun. If folks are interested in, I guess if you're cool with it, can they reach out to you if they want to learn more, can they reach out to Origin if they want to learn more?\n\nJohn Entwistle (53:46): Absolutely. Yeah, I'm always down for a beer. Feel free to message me honestly. Direct messages on Instagram, you can find me at entel photo and then, yeah, I dunno, we will, we put the links to social and everything in the description of the podcast here. Yeah, yeah. Perfect. So yeah, email, Instagram, any of that is definitely good to reach out.\n\nCole Heilborn (54:08): Okay, cool. Well, John, I want to thank you for your time. I want to thank you for closing out our freelance month and I think this was a lot of fun. I feel like there's a lot of great tangible good practices in this episode. So I appreciate you sharing your thoughts and perspective on this issue.", "token_estimate": 533, "speakers": ["John Entwistle", "Cole Heilborn"], "start_timestamp": "52:27", "end_timestamp": "54:08", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "fc681488-2a51-4895-b61f-6009d5f42466", "episode_id": "f8b871bf-fda9-4b05-8296-56cb89962d1d", "cms_item_id": "68225dfc7bb476527f8c488d", "chunk_index": 26, "content": "John Entwistle (54:24): For sure. Thanks, Cole. Hopefully somebody, you find something useful in there and like I said, I'll probably go listen back to it myself.\n\nCole Heilborn (54:30): Alright, well have a great rest of your day and yeah, we'll chat soon.\n\nJohn Entwistle (54:35): Great. Thanks Cole. Talk soon. Bye.\n\nCole Heilborn (54:39): Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 139, "speakers": ["John Entwistle", "Cole Heilborn"], "start_timestamp": "54:24", "end_timestamp": "54:39", "podcast_index": 98, "episode_name": "Ep 98: How to Work with An Agency | John Entwistle | Origin", "slug": "ep-98-how-to-work-with-an-agency-john-entwistle-origin", "web_url": "https://www.portsidepro.com/podcast-feed/ep-98-how-to-work-with-an-agency-john-entwistle-origin", "guest_name": "John Entwhistle", "guest_title": "Account Director at Origin", "categories": ["leadership-and-people"], "short_description": "This week, Cole sits down with John Entwistle, Account Director and Photographer at Origin, an outdoor agency that partners with brands they believe in. Everything they do is about getting more people out there.", "podcast_length": "54:58"}, {"id": "8864e384-261a-4137-84f1-6220fcf7fd9d", "episode_id": "8d8ebe7a-5cd3-43e7-ad82-76ba53105198", "cms_item_id": "68225dfc7bb476527f8c488c", "chunk_index": 0, "content": "Kaim York-Feirn (00:03): Rough wear is a very adventurous and playful brand because when you think about dogs, you think about those aspects. So they're very dury and goofy and playful, and they are your best friends. They are your adventure buddy. And so that was pretty easy for us to come up with those adjectives when thinking about Instagram because we not only want to be relatable, but we also want to show that the outdoors are a space for every person, every dog, every type of adventure.\n\nCole Heilborn (00:33): Welcome to the Backcountry Marketing podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo, and today I'm sitting down with Camie York Fern. She's the social media coordinator over at Ruff Ware Camie. How are you doing?\n\nKaim York-Feirn (01:16): I'm good, Cole. How are you doing?\n\nCole Heilborn (01:18): I'm doing wonderful. It's a sunny ish day up here in Bellingham, and actually as I was preparing for our conversation, I was getting distracted by the sun and was thinking about all the things that I would like to be doing this afternoon once we're done recording. So we'll see if I get around to doing any of them.\n\nKaim York-Feirn (01:36): Well, it's a nice sunny day over here in Sun Valley too. I took my dog for a walk to prepare for this recording, and I'm going to go for a hike with my boss a little bit later.", "token_estimate": 473, "speakers": ["Kaim York-Feirn", "Cole Heilborn"], "start_timestamp": "00:03", "end_timestamp": "01:36", "podcast_index": 99, "episode_name": "Ep 99: How to Find Your Brand Voice on Social | Kami York-Feirn | Ruffwear", "slug": "ep-99-how-to-find-your-brand-voice-on-social-kami-york-feirn-ruffwear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-99-how-to-find-your-brand-voice-on-social-kami-york-feirn-ruffwear", "guest_name": "Kami York-Feirn", "guest_title": "Social Media Coordinator", "categories": ["digital-marketing"], "short_description": "Social media is constantly changing, new algorithms, new platforms, and new trends are a daily occurrence. As a brand, how do you decide what platforms to be present on? How does your brand communicate on each platform?", "podcast_length": "58:20"}, {"id": "1b87d6d2-31e3-46a7-ad12-1d876645607a", "episode_id": "8d8ebe7a-5cd3-43e7-ad82-76ba53105198", "cms_item_id": "68225dfc7bb476527f8c488c", "chunk_index": 1, "content": "Cole Heilborn (01:48): Well, that sounds like a wonderful way to spend the day. Congrats on the recent position with rough Wear. You've recently accepted this role and I got to imagine a lot of people are kind of jealous of a job at Rough Wear on the outside. I have ideas of what maybe it's like to work there, but what is it like now that you've been there for a little bit of time?\n\nKaim York-Feirn (02:11): Yeah, thank you. I am really enjoying my time here. You cannot have a bad day when you work with dogs. Things are going really well. I love the team and our collaborative environment that they've created, and we are now a fully remote team. I think that happened about a year or so ago because of the pandemic, and so that allows us to work from anywhere. So I said that I was going to go for a hike with my boss this afternoon. She's actually visiting Sun Valley to take an AbbVie course this weekend, I think. So it's been really great to get to know my coworkers and be able to work from anywhere.\n\nCole Heilborn (02:52): Because Rough Wear is based in Bend, correct?\n\nKaim York-Feirn (02:55): Yes.\n\nCole Heilborn (02:56): Okay. And do you guys only make products for dogs?\n\nKaim York-Feirn (03:02): We do. That is our specialty, so we do collars, leashes, harnesses, toys, you name it for a dog, we make it.\n\nCole Heilborn (03:10): Okay. Are there any people in the office who prefer cats over dogs? How does that go down?\n\nKaim York-Feirn (03:17): Yeah, there are definitely people in the office who are more cat people. There are a few who don't own dogs, and that's totally okay. I am a dog person over a cat person just because I am allergic to cats. I have never really liked small things. I like taking my dog out for hikes. I don't really often see cats out on the trail.\n\nCole Heilborn (03:41): Yeah, one of these days it'll be a thing though. I just give it enough time.\n\nKaim York-Feirn (03:47): Adventure Cat, maybe that'll be the next big thing on Instagram.", "token_estimate": 497, "speakers": ["Cole Heilborn", "Kaim York-Feirn"], "start_timestamp": "01:48", "end_timestamp": "03:47", "podcast_index": 99, "episode_name": "Ep 99: How to Find Your Brand Voice on Social | Kami York-Feirn | Ruffwear", "slug": "ep-99-how-to-find-your-brand-voice-on-social-kami-york-feirn-ruffwear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-99-how-to-find-your-brand-voice-on-social-kami-york-feirn-ruffwear", "guest_name": "Kami York-Feirn", "guest_title": "Social Media Coordinator", "categories": ["digital-marketing"], "short_description": "Social media is constantly changing, new algorithms, new platforms, and new trends are a daily occurrence. As a brand, how do you decide what platforms to be present on? How does your brand communicate on each platform?", "podcast_length": "58:20"}, {"id": "5bb097ed-ccb3-498d-84b9-57e770256954", "episode_id": "8d8ebe7a-5cd3-43e7-ad82-76ba53105198", "cms_item_id": "68225dfc7bb476527f8c488c", "chunk_index": 2, "content": "Cole Heilborn (03:49): Yeah, there we go. Well, Cammie, I'm stoked to have you on the show. I'm excited for our conversation today. We're going to be diving into the topic of brand voice and how that translates onto social media. Before we get into that though, I've got a few rapid fire questions for folks just to kind of warm you up and let people know a little bit more about who you are. So well actually, I guess I know the answer to this first question based on your introduction here, but if you had to choose between coffee or tea, what would you choose?\n\nKaim York-Feirn (04:21): Coffee, 100%. I'm a vanilla latte or white chocolate mocha kind of girl.\n\nCole Heilborn (04:27): Okay. And if you're listening to music, are you going to choose Spotify to listen on or Apple Music?\n\nKaim York-Feirn (04:34): Spotify for sure. I think they have a wider range of stuff. I like to listen to Rap Country alternative pop. Pretty much anything is okay except I don't do heavy metal or screamo.\n\nCole Heilborn (04:50): Okay, fair enough. Did you take any trips last year? And if so, what was your favorite or activities or something fun?\n\nKaim York-Feirn (04:58): I would say my favorite trip was to bend Oregon before I started working at Rough Wear. I went last summer for a mountain biking trip. We went for a full week and we did a scoot tour on electric scooters. We mountain biked every day, went to a lot of breweries, checked out a bunch of new places. I had never been to Oregon before and was blown away by the rainforest and how amazing the dirt was for mountain biking.\n\nCole Heilborn (05:30): Awesome. Well, that sounds like a great way to spend your time. And I know you do social media work. Do you have a favorite social media platform\n\nKaim York-Feirn (05:41): To post on and engage with? I'll say Instagram. I love TikTok, but I only have posted a few videos and I prefer to watch more. I don't know if that's creepy or not, but\n\nCole Heilborn (05:56): Okay, cool. Well, let's dive in. So tell us a little bit, maybe first about your role with Rough Wear, what you do, what you oversee.", "token_estimate": 526, "speakers": ["Cole Heilborn", "Kaim York-Feirn"], "start_timestamp": "03:49", "end_timestamp": "05:56", "podcast_index": 99, "episode_name": "Ep 99: How to Find Your Brand Voice on Social | Kami York-Feirn | Ruffwear", "slug": "ep-99-how-to-find-your-brand-voice-on-social-kami-york-feirn-ruffwear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-99-how-to-find-your-brand-voice-on-social-kami-york-feirn-ruffwear", "guest_name": "Kami York-Feirn", "guest_title": "Social Media Coordinator", "categories": ["digital-marketing"], "short_description": "Social media is constantly changing, new algorithms, new platforms, and new trends are a daily occurrence. As a brand, how do you decide what platforms to be present on? How does your brand communicate on each platform?", "podcast_length": "58:20"}, {"id": "ccae36f1-fed4-45c5-af61-b9a1aadc8689", "episode_id": "8d8ebe7a-5cd3-43e7-ad82-76ba53105198", "cms_item_id": "68225dfc7bb476527f8c488c", "chunk_index": 3, "content": "Kaim York-Feirn (06:07): As the social media coordinator, I work very closely with our marketing and creative teams on our strategy across social media in general. So that includes our blog, our Instagram channel, our Facebook page, and then also looking at new and emerging platforms such as TikTok. Okay,\n\nCole Heilborn (06:25): Gotcha. So we connected a couple months ago and we started talking about some possible topics and this idea of finding your brand voice or taking the brand voice of a company and figuring out how to present it on social. We're going to kind of dive into the weeds in this topic, but first if you could just set up what is the challenge with this idea that you work on with brands day to day?\n\nKaim York-Feirn (06:51): Yeah, I think the challenge when defining brand voice is brands often want to put the cart before the horse. And by that I mean deciding to post on a certain platform before they have a strategy for that specific platform and knowing how they would describe their brand to customers. So I think it's really important to come up with adjectives that describe who you are as a brand. Are you adventurous and playful? Do you create high quality products? Are you forward thinking? Then come up with the adjectives that you are not, we're not frilly, we're not serious, we're not elitist, those types of things. And so the biggest challenge that I see is brands trying to get on emerging platforms before they have established who they are internally.\n\nCole Heilborn (07:43): Gotcha. I guess I'm thinking about Clubhouse as you're talking about emerging platforms, that seems to be a platform that emerged recently. I don't even know if it's still active or not, but it feels like when that popped up, it became all the rage and everyone jumped to it, and I think there was a lot of people, a lot of individual personalities that were on it, maybe more so than brand voices. I'm curious in that instance, did you see any brands trying to figure that out?", "token_estimate": 500, "speakers": ["Kaim York-Feirn", "Cole Heilborn"], "start_timestamp": "06:07", "end_timestamp": "07:43", "podcast_index": 99, "episode_name": "Ep 99: How to Find Your Brand Voice on Social | Kami York-Feirn | Ruffwear", "slug": "ep-99-how-to-find-your-brand-voice-on-social-kami-york-feirn-ruffwear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-99-how-to-find-your-brand-voice-on-social-kami-york-feirn-ruffwear", "guest_name": "Kami York-Feirn", "guest_title": "Social Media Coordinator", "categories": ["digital-marketing"], "short_description": "Social media is constantly changing, new algorithms, new platforms, and new trends are a daily occurrence. As a brand, how do you decide what platforms to be present on? How does your brand communicate on each platform?", "podcast_length": "58:20"}, {"id": "5776ead1-b9b9-406d-8ea1-168ca03b015d", "episode_id": "8d8ebe7a-5cd3-43e7-ad82-76ba53105198", "cms_item_id": "68225dfc7bb476527f8c488c", "chunk_index": 4, "content": "Kaim York-Feirn (08:10): I did see quite a few brands on Clubhouse, and it's funny that you bring that up because that's a perfect example of a platform that became all the rage and then kind of died out. So people jumped onto Clubhouse without really knowing or understanding what the platform was and they learned as they went, which is an okay strategy. But I think that when you're talking about platforms that stick around Instagram and TikTok and Facebook, it's very important to have a cohesive posting strategy in terms of what do you want to sound like? Is your audience there and how can we meet them there and create engaging content for that specific platform? So Clubhouse was more of a interaction platform where you got on and you could have discussions with other people about a very specific topic, but you had to be invited. It was also exclusive. I remember getting an invite from someone that worked at our PR agency and I was so excited, but then I got on and I didn't really understand how to use the platform. There wasn't a how to or instructions on how to be invited to a specific room or how to start your own room. And so while I was excited by it and excited to follow the brands that we're posting, I never fully grasped or understood the platform.\n\nCole Heilborn (09:38): That seems to be a common story, does it not? A platform pops up and it's awesome, and then it just kind of disappears into the ether. Why is that? Why does some catch and stick and change everything and why does some just get us all excited and then we delete it three months later?", "token_estimate": 397, "speakers": ["Kaim York-Feirn", "Cole Heilborn"], "start_timestamp": "08:10", "end_timestamp": "09:38", "podcast_index": 99, "episode_name": "Ep 99: How to Find Your Brand Voice on Social | Kami York-Feirn | Ruffwear", "slug": "ep-99-how-to-find-your-brand-voice-on-social-kami-york-feirn-ruffwear", "web_url": "https://www.portsidepro.com/podcast-feed/ep-99-how-to-find-your-brand-voice-on-social-kami-york-feirn-ruffwear", "guest_name": "Kami York-Feirn", "guest_title": "Social Media Coordinator", "categories": ["digital-marketing"], "short_description": "Social media is constantly changing, new algorithms, new platforms, and new trends are a daily occurrence. As a brand, how do you decide what platforms to be present on? How does your brand communicate on each platform?", "podcast_length": "58:20"}]
